import type { BankQuestion } from "@/lib/bank";

/** Indian Art and Culture (History): 188 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"history-art-culture-1","question":"Kathakali, the classical dance-drama, belongs to which state?","options":["Tamil Nadu","Kerala","Karnataka","Odisha"],"answer":1,"explanation":"Kathakali is from Kerala. Bharatanatyam is from Tamil Nadu and Odissi from Odisha.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"शास्त्रीय नृत्य-नाटिका कथकली किस राज्य से संबंधित है?","optionsHi":["तमिलनाडु","केरल","कर्नाटक","ओडिशा"],"explanationHi":"कथकली केरल की है। भरतनाट्यम तमिलनाडु का और ओडिसी ओडिशा का नृत्य है।"},
  {"id":"history-art-culture-2","question":"The Sun Temple at Konark is in:","options":["Odisha","West Bengal","Gujarat","Andhra Pradesh"],"answer":0,"explanation":"The Konark Sun Temple, built by the Eastern Ganga king Narasimhadeva I in the 13th century, stands on the Odisha coast. Modhera in Gujarat has another Sun temple.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"कोणार्क का सूर्य मंदिर कहाँ स्थित है?","optionsHi":["ओडिशा","पश्चिम बंगाल","गुजरात","आंध्र प्रदेश"],"explanationHi":"13वीं शताब्दी में पूर्वी गंग राजा नरसिंहदेव प्रथम द्वारा बनवाया गया कोणार्क सूर्य मंदिर ओडिशा के तट पर स्थित है। गुजरात के मोढेरा में एक अन्य सूर्य मंदिर है।"},
  {"id":"history-art-culture-3","question":"The Ajanta caves, famous for their Buddhist wall paintings, are in:","options":["Madhya Pradesh","Karnataka","Maharashtra","Bihar"],"answer":2,"explanation":"Ajanta is in Aurangabad (Chhatrapati Sambhajinagar) district, Maharashtra, as is Ellora.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"बौद्ध भित्ति चित्रों के लिए प्रसिद्ध अजंता की गुफाएँ कहाँ स्थित हैं?","optionsHi":["मध्य प्रदेश","कर्नाटक","महाराष्ट्र","बिहार"],"explanationHi":"अजंता महाराष्ट्र के औरंगाबाद (छत्रपति संभाजीनगर) जिले में है, एलोरा भी वहीं है।"},
  {"id":"history-art-culture-4","question":"Bihu is the main festival of:","options":["Assam","Punjab","Kerala","Tamil Nadu"],"answer":0,"explanation":"Bihu, celebrated three times a year (Rongali, Kongali and Bhogali), is Assam’s main festival.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"बिहू किस राज्य का प्रमुख त्योहार है?","optionsHi":["असम","पंजाब","केरल","तमिलनाडु"],"explanationHi":"बिहू वर्ष में तीन बार (रोंगाली, कोंगाली और भोगाली) मनाया जाता है और यह असम का प्रमुख त्योहार है।"},
  {"id":"history-art-culture-5","question":"Kuchipudi takes its name from a village in:","options":["Tamil Nadu","Karnataka","Telangana (Warangal)","Andhra Pradesh"],"answer":3,"explanation":"Kuchipudi village is in Krishna district of Andhra Pradesh, where the Bhagavata Mela tradition of the dance grew.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"कुचिपुड़ी का नाम किस राज्य के एक गाँव के नाम पर पड़ा है?","optionsHi":["तमिलनाडु","कर्नाटक","तेलंगाना (वारंगल)","आंध्र प्रदेश"],"explanationHi":"कुचिपुड़ी गाँव आंध्र प्रदेश के कृष्णा जिले में है, जहाँ इस नृत्य की भागवत मेला परंपरा विकसित हुई।"},
  {"id":"history-art-culture-6","question":"The Sattriya dance grew in the Vaishnava monasteries (sattras) of:","options":["Manipur","Assam","Odisha","Tripura"],"answer":1,"explanation":"Sattriya developed in the sattras of Assam from the 15th–16th century; the Sangeet Natak Akademi recognised it as classical in 2000.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"सत्रीया नृत्य किस राज्य के वैष्णव मठों (सत्रों) में विकसित हुआ?","optionsHi":["मणिपुर","असम","ओडिशा","त्रिपुरा"],"explanationHi":"सत्रीया 15वीं-16वीं शताब्दी से असम के सत्रों में विकसित हुआ; संगीत नाटक अकादमी ने इसे 2000 में शास्त्रीय नृत्य की मान्यता दी।"},
  {"id":"history-art-culture-7","question":"Madhubani (Mithila) painting is a folk art of:","options":["Bihar","Odisha","Rajasthan","Gujarat"],"answer":0,"explanation":"Madhubani painting comes from the Mithila region of Bihar and has a GI tag.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"मधुबनी (मिथिला) चित्रकला किस राज्य की लोक कला है?","optionsHi":["बिहार","ओडिशा","राजस्थान","गुजरात"],"explanationHi":"मधुबनी चित्रकला बिहार के मिथिला क्षेत्र की है और इसे GI टैग प्राप्त है।"},
  {"id":"history-art-culture-8","question":"The temples of Khajuraho were built by the:","options":["Paramaras","Chandelas","Solankis","Gahadavalas"],"answer":1,"explanation":"The Chandela rulers of Bundelkhand built the Khajuraho temples between about 950 and 1050.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"खजुराहो के मंदिरों का निर्माण किसने करवाया था?","optionsHi":["परमारों ने","चंदेलों ने","सोलंकियों ने","गहड़वालों ने"],"explanationHi":"बुंदेलखंड के चंदेल शासकों ने लगभग 950 से 1050 के बीच खजुराहो के मंदिर बनवाए।"},
  {"id":"history-art-culture-9","question":"A temple with a stepped pyramidal tower (vimana) over the sanctum and tall gateway towers (gopurams) belongs to which style?","options":["Nagara","Vesara","Dravida","Kalinga"],"answer":2,"explanation":"The Dravida style of south India has a vimana over the sanctum and gopurams at the entrances; the Nagara style has a curvilinear shikhara.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"गर्भगृह के ऊपर सीढ़ीदार पिरामिडनुमा शिखर (विमान) और ऊँचे प्रवेश-द्वार मीनारों (गोपुरम) वाला मंदिर किस शैली का है?","optionsHi":["नागर","वेसर","द्रविड़","कलिंग"],"explanationHi":"दक्षिण भारत की द्रविड़ शैली में गर्भगृह के ऊपर विमान और प्रवेश द्वारों पर गोपुरम होते हैं; नागर शैली में वक्ररेखीय शिखर होता है।"},
  {"id":"history-art-culture-10","question":"Warli painting, made with white paste on mud walls, is the art of a tribe of:","options":["Maharashtra","Jharkhand","Chhattisgarh","Madhya Pradesh"],"answer":0,"explanation":"The Warli tribe lives in the Thane and Palghar region of Maharashtra. Gond painting comes from Madhya Pradesh.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"मिट्टी की दीवारों पर सफेद लेई से बनाई जाने वाली वारली चित्रकला किस राज्य की जनजाति की कला है?","optionsHi":["महाराष्ट्र","झारखंड","छत्तीसगढ़","मध्य प्रदेश"],"explanationHi":"वारली जनजाति महाराष्ट्र के ठाणे और पालघर क्षेत्र में रहती है। गोंड चित्रकला मध्य प्रदेश की है।"},
  {"id":"history-art-culture-11","question":"Which of the following is NOT one of the Trinity of Carnatic music?","options":["Tyagaraja","Muthuswami Dikshitar","Syama Sastri","Purandaradasa"],"answer":3,"explanation":"The Trinity are Tyagaraja, Muthuswami Dikshitar and Syama Sastri (18th–19th century). Purandaradasa (16th century) is called the father of Carnatic music.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"निम्नलिखित में से कौन कर्नाटक संगीत की त्रिमूर्ति में शामिल नहीं है?","optionsHi":["त्यागराज","मुत्तुस्वामी दीक्षितार","श्यामा शास्त्री","पुरंदरदास"],"explanationHi":"त्रिमूर्ति में त्यागराज, मुत्तुस्वामी दीक्षितार और श्यामा शास्त्री (18वीं-19वीं शताब्दी) हैं। पुरंदरदास (16वीं शताब्दी) को कर्नाटक संगीत का पितामह कहा जाता है।"},
  {"id":"history-art-culture-12","question":"The Hornbill Festival is held every December in:","options":["Mizoram","Nagaland","Arunachal Pradesh","Manipur"],"answer":1,"explanation":"Nagaland holds the Hornbill Festival at Kisama near Kohima from 1 to 10 December.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"हॉर्नबिल महोत्सव प्रत्येक दिसंबर में कहाँ आयोजित होता है?","optionsHi":["मिज़ोरम","नागालैंड","अरुणाचल प्रदेश","मणिपुर"],"explanationHi":"नागालैंड कोहिमा के पास किसामा में 1 से 10 दिसंबर तक हॉर्नबिल महोत्सव आयोजित करता है।"},
  {"id":"history-art-culture-13","question":"The Vesara style of temple architecture, a blend of Nagara and Dravida features, is chiefly associated with:","options":["Pallavas of Kanchipuram","Later Chalukyas and Hoysalas","Imperial Cholas of Thanjavur","Eastern Gangas of Odisha"],"answer":1,"explanation":"Vesara flourished in the Deccan under the later Chalukyas and the Hoysalas. The Pallavas and Cholas built in the Dravida style, and the Gangas of Odisha in the Kalinga variant of Nagara.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मंदिर स्थापत्य की वेसर शैली, जिसमें नागर और द्रविड़ दोनों की विशेषताओं का मिश्रण है, मुख्यतः किससे संबंधित है?","optionsHi":["कांचीपुरम के पल्लव","परवर्ती चालुक्य और होयसल","तंजावुर के साम्राज्यिक चोल","ओडिशा के पूर्वी गंग"],"explanationHi":"वेसर शैली दक्कन में परवर्ती चालुक्यों और होयसलों के अधीन फली-फूली। पल्लवों और चोलों ने द्रविड़ शैली में निर्माण किया, और ओडिशा के गंगों ने नागर की कलिंग शैली में।"},
  {"id":"history-art-culture-14","question":"The rock-cut Kailasa temple at Ellora was carved under:","options":["Rashtrakuta king Krishna I","Chalukya king Pulakeshin II","Pallava king Mahendravarman I","Rashtrakuta king Amoghavarsha"],"answer":0,"explanation":"The monolithic Kailasa temple (cave 16) was carved in the reign of Krishna I in the 8th century.","difficulty":"hard","source":"UPSC Prelims","questionHi":"एलोरा का चट्टान काटकर बना कैलास मंदिर किसके शासनकाल में तराशा गया?","optionsHi":["राष्ट्रकूट राजा कृष्ण प्रथम","चालुक्य राजा पुलकेशिन द्वितीय","पल्लव राजा महेंद्रवर्मन प्रथम","राष्ट्रकूट राजा अमोघवर्ष"],"explanationHi":"एकाश्म कैलास मंदिर (गुफा 16) 8वीं शताब्दी में कृष्ण प्रथम के शासनकाल में तराशा गया।"},
  {"id":"history-art-culture-15","question":"The Shore Temple at Mamallapuram was built by:","options":["Mahendravarman I (Vichitrachitta)","Narasimhavarman I (Mamalla)","Narasimhavarman II (Rajasimha)","Nandivarman II (Pallavamalla)"],"answer":2,"explanation":"Narasimhavarman II (Rajasimha) built the structural Shore Temple around 700. Narasimhavarman I (Mamalla) is linked with the rock-cut rathas.","difficulty":"hard","source":"UPSC Prelims","questionHi":"महाबलीपुरम का तट मंदिर किसने बनवाया?","optionsHi":["महेंद्रवर्मन प्रथम (विचित्रचित्त)","नरसिंहवर्मन प्रथम (ममल्ल)","नरसिंहवर्मन द्वितीय (राजसिंह)","नंदिवर्मन द्वितीय (पल्लवमल्ल)"],"explanationHi":"नरसिंहवर्मन द्वितीय (राजसिंह) ने लगभग 700 में संरचनात्मक तट मंदिर बनवाया। नरसिंहवर्मन प्रथम (ममल्ल) का संबंध चट्टान काटकर बने रथों से है।"},
  {"id":"history-art-culture-16","question":"Pattachitra, painting on cloth depicting the Jagannath cult and epic stories, is chiefly associated with:","options":["Odisha","Rajasthan","Kerala","Telangana"],"answer":0,"explanation":"Pattachitra is the traditional cloth painting of Odisha, centred on Puri and the village of Raghurajpur.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"जगन्नाथ संप्रदाय और महाकाव्य कथाओं को दर्शाने वाली कपड़े पर बनी पट्टचित्र चित्रकला मुख्यतः किस राज्य से संबंधित है?","optionsHi":["ओडिशा","राजस्थान","केरल","तेलंगाना"],"explanationHi":"पट्टचित्र ओडिशा की परंपरागत कपड़े पर बनी चित्रकला है, जिसका केंद्र पुरी और रघुराजपुर गाँव है।"},
  {"id":"history-art-culture-17","question":"Kalamkari, hand-painted or block-printed textile art, is chiefly associated with Srikalahasti and Machilipatnam in:","options":["Tamil Nadu","Andhra Pradesh","Gujarat","Madhya Pradesh"],"answer":1,"explanation":"Srikalahasti (pen-drawn) and Machilipatnam (block-printed) Kalamkari are from Andhra Pradesh. Gujarat's similar temple cloth is Mata ni Pachedi, and Madhya Pradesh is known for Bagh block printing.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"हाथ से रंगी या ब्लॉक से छपी वस्त्र कला कलमकारी मुख्यतः किस राज्य के श्रीकालहस्ती और मछलीपट्टनम से संबंधित है?","optionsHi":["तमिलनाडु","आंध्र प्रदेश","गुजरात","मध्य प्रदेश"],"explanationHi":"श्रीकालहस्ती (कलम से बनी) और मछलीपट्टनम (ब्लॉक से छपी) कलमकारी आंध्र प्रदेश की हैं। गुजरात का इसी प्रकार का मंदिर वस्त्र 'माता नी पछेड़ी' है, और मध्य प्रदेश बाघ ब्लॉक प्रिंटिंग के लिए जाना जाता है।"},
  {"id":"history-art-culture-18","question":"Kalakshetra, the institution that helped revive Bharatanatyam in the 20th century, was founded in 1936 by:","options":["Rukmini Devi Arundale","Vallathol Narayana Menon","Mrinalini Sarabhai","Yamini Krishnamurthy"],"answer":0,"explanation":"Rukmini Devi Arundale founded Kalakshetra at Adyar, Madras, in 1936. Vallathol founded the Kerala Kalamandalam (1930) for Kathakali, and Mrinalini Sarabhai founded Darpana in Ahmedabad.","difficulty":"hard","source":"UPSC Prelims","questionHi":"20वीं शताब्दी में भरतनाट्यम के पुनरुद्धार में सहायक संस्था कलाक्षेत्र की स्थापना 1936 में किसने की थी?","optionsHi":["रुक्मिणी देवी अरुंडेल","वल्लथोल नारायण मेनन","मृणालिनी साराभाई","यामिनी कृष्णमूर्ति"],"explanationHi":"रुक्मिणी देवी अरुंडेल ने 1936 में मद्रास के अड्यार में कलाक्षेत्र की स्थापना की। वल्लथोल ने कथकली के लिए केरल कलामंडलम (1930) और मृणालिनी साराभाई ने अहमदाबाद में दर्पणा की स्थापना की।"},
  {"id":"history-art-culture-19","question":"How many classical dance forms are recognised by the Sangeet Natak Akademi?","options":["Six","Seven","Eight","Nine"],"answer":2,"explanation":"The Akademi recognises eight: Bharatanatyam, Kathak, Kathakali, Kuchipudi, Manipuri, Mohiniyattam, Odissi and Sattriya. The Ministry of Culture also counts Chhau, making nine on its list.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"संगीत नाटक अकादमी द्वारा कितने शास्त्रीय नृत्य रूपों को मान्यता प्राप्त है?","optionsHi":["छह","सात","आठ","नौ"],"explanationHi":"अकादमी आठ को मान्यता देती है: भरतनाट्यम, कथक, कथकली, कुचिपुड़ी, मणिपुरी, मोहिनीअट्टम, ओडिसी और सत्रीया। संस्कृति मंत्रालय छऊ को भी गिनता है, जिससे उसकी सूची में नौ हो जाते हैं।"},
  {"id":"history-art-culture-20","question":"Which is regarded as the oldest surviving form of Hindustani classical vocal music, kept alive by the Dagar family?","options":["Khayal","Thumri","Tappa","Dhrupad"],"answer":3,"explanation":"Dhrupad, rooted in temple music and patronised at Gwalior and the Mughal court, is the oldest; Khayal, Thumri and Tappa developed later.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"हिंदुस्तानी शास्त्रीय गायन का सबसे प्राचीन जीवित रूप कौन-सा माना जाता है, जिसे डागर परिवार ने जीवित रखा है?","optionsHi":["ख़याल","ठुमरी","टप्पा","ध्रुपद"],"explanationHi":"मंदिर संगीत में जड़ें रखने वाला तथा ग्वालियर और मुगल दरबार में संरक्षित ध्रुपद सबसे प्राचीन है; ख़याल, ठुमरी और टप्पा बाद में विकसित हुए।"},
  {"id":"history-art-culture-21","question":"The Gita Govinda, whose songs are central to the Odissi dance repertoire, was composed by:","options":["Jayadeva","Vidyapati","Chandidas","Kalidasa"],"answer":0,"explanation":"Jayadeva, a 12th-century poet, wrote the Gita Govinda in Sanskrit; its ashtapadis are sung in Odissi performances.","difficulty":"hard","source":"UPSC Prelims","questionHi":"गीत गोविंद, जिसके गीत ओडिसी नृत्य के प्रदर्शन-संग्रह के केंद्र में हैं, की रचना किसने की?","optionsHi":["जयदेव","विद्यापति","चंडीदास","कालिदास"],"explanationHi":"12वीं शताब्दी के कवि जयदेव ने संस्कृत में गीत गोविंद की रचना की; इसकी अष्टपदियाँ ओडिसी प्रस्तुतियों में गाई जाती हैं।"},
  {"id":"history-art-culture-22","question":"Durga Puja in Kolkata was added to UNESCO’s list of the Intangible Cultural Heritage of Humanity in:","options":["2016","2019","2021","2023"],"answer":2,"explanation":"Durga Puja in Kolkata was inscribed in December 2021. Garba of Gujarat followed in 2023, and Yoga in 2016.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कोलकाता की दुर्गा पूजा को यूनेस्को की मानवता की अमूर्त सांस्कृतिक विरासत की सूची में किस वर्ष शामिल किया गया?","optionsHi":["2016","2019","2021","2023"],"explanationHi":"कोलकाता की दुर्गा पूजा दिसंबर 2021 में सूची में शामिल हुई। गुजरात का गरबा 2023 में और योग 2016 में शामिल हुआ।"},
  {"id":"history-art-culture-23","question":"Rani-ki-Vav, the stepwell at Patan inscribed as a World Heritage Site in 2014, was built by:","options":["Rani Rudrama Devi of the Kakatiyas","Queen Udayamati, widow of Bhima I","Rani Durgavati of Gondwana","Queen Ahilyabai Holkar"],"answer":1,"explanation":"Queen Udayamati built Rani-ki-Vav in the 11th century in memory of her husband Bhima I of the Chaulukya (Solanki) dynasty.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पाटन की बावड़ी रानी-की-वाव, जो 2014 में विश्व धरोहर स्थल घोषित हुई, किसने बनवाई थी?","optionsHi":["काकतीयों की रानी रुद्रमा देवी","रानी उदयमती, भीम प्रथम की विधवा","गोंडवाना की रानी दुर्गावती","रानी अहिल्याबाई होल्कर"],"explanationHi":"रानी उदयमती ने 11वीं शताब्दी में चौलुक्य (सोलंकी) वंश के अपने पति भीम प्रथम की स्मृति में रानी-की-वाव बनवाई।"},
  {"id":"history-art-culture-24","question":"The Vimala Vasahi, the oldest of the Dilwara temples at Mount Abu, was built in 1031 by:","options":["Brothers Vastupala and Tejapala","Vimal Shah, minister of Bhima I","Rana Kumbha","Kumarapala"],"answer":1,"explanation":"Vimal Shah built the Vimala Vasahi, dedicated to Adinatha. The Luna Vasahi was built in 1230 by the brothers Vastupala and Tejapala.","difficulty":"hard","source":"UPSC Prelims","questionHi":"माउंट आबू के दिलवाड़ा मंदिरों में सबसे प्राचीन विमल वसही का निर्माण 1031 में किसने करवाया?","optionsHi":["भाई वस्तुपाल और तेजपाल","विमल शाह, भीम प्रथम का मंत्री","राणा कुंभा","कुमारपाल"],"explanationHi":"विमल शाह ने आदिनाथ को समर्पित विमल वसही बनवाया। लूण वसही 1230 में भाइयों वस्तुपाल और तेजपाल ने बनवाया।"},
  {"id":"history-art-culture-25","question":"Match the classical dance with its state: A. Mohiniyattam B. Kuchipudi C. Sattriya D. Odissi — 1. Assam 2. Odisha 3. Kerala 4. Andhra Pradesh","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1"],"answer":0,"explanation":"Mohiniyattam – Kerala; Kuchipudi – Andhra Pradesh; Sattriya – Assam; Odissi – Odisha.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"शास्त्रीय नृत्य का उसके राज्य से मिलान कीजिए: A. मोहिनीअट्टम B. कुचिपुड़ी C. सत्रीया D. ओडिसी — 1. असम 2. ओडिशा 3. केरल 4. आंध्र प्रदेश","optionsHi":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1"],"explanationHi":"मोहिनीअट्टम – केरल; कुचिपुड़ी – आंध्र प्रदेश; सत्रीया – असम; ओडिसी – ओडिशा।"},
  {"id":"history-art-culture-26","question":"How many of these statements about Chhau dance are correct? I. Its three styles are Purulia, Seraikela and Mayurbhanj. II. Mayurbhanj Chhau is performed without masks. III. It was inscribed on UNESCO’s intangible heritage list in 2010. IV. It is one of the eight classical dances recognised by the Sangeet Natak Akademi.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Chhau is not among the Akademi’s eight classical dances, though the Ministry of Culture lists it.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"छऊ नृत्य के बारे में इनमें से कितने कथन सही हैं? I. इसकी तीन शैलियाँ पुरुलिया, सरायकेला और मयूरभंज हैं। II. मयूरभंज छऊ बिना मुखौटे के किया जाता है। III. इसे 2010 में यूनेस्को की अमूर्त विरासत सूची में शामिल किया गया। IV. यह संगीत नाटक अकादमी द्वारा मान्यता प्राप्त आठ शास्त्रीय नृत्यों में से एक है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। छऊ अकादमी के आठ शास्त्रीय नृत्यों में नहीं है, हालाँकि संस्कृति मंत्रालय इसे सूचीबद्ध करता है।"},
  {"id":"history-art-culture-27","question":"Arrange these monuments by when they were built: 1. Kailasa temple, Ellora 2. Core of the Great Stupa, Sanchi 3. Qutb Minar (begun) 4. Kandariya Mahadeva temple, Khajuraho","options":["2-1-3-4","2-4-1-3","1-2-4-3","2-1-4-3"],"answer":3,"explanation":"Sanchi stupa core under Ashoka (3rd century BCE), Kailasa (8th century), Kandariya Mahadeva (about 1030), Qutb Minar begun by Aibak (about 1199).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन स्मारकों को उनके निर्माण के समय के अनुसार व्यवस्थित कीजिए: 1. कैलास मंदिर, एलोरा 2. साँची के महान स्तूप का मूल भाग 3. कुतुब मीनार (आरंभ) 4. कंदरिया महादेव मंदिर, खजुराहो","optionsHi":["2-1-3-4","2-4-1-3","1-2-4-3","2-1-4-3"],"explanationHi":"साँची स्तूप का मूल भाग अशोक के काल में (तीसरी शताब्दी ई.पू.), कैलास (8वीं शताब्दी), कंदरिया महादेव (लगभग 1030), कुतुब मीनार ऐबक द्वारा आरंभ (लगभग 1199)।"},
  {"id":"history-art-culture-28","question":"Which pair of painting school and region is NOT correctly matched?","options":["Kangra – Himachal Pradesh","Kalighat – West Bengal","Basohli – Jammu and Kashmir","Kishangarh – Gujarat"],"answer":3,"explanation":"Kishangarh, famous for the Bani Thani portrait, is a Rajasthani school. The other three pairs are correct.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"चित्रकला शैली और क्षेत्र का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["कांगड़ा – हिमाचल प्रदेश","कालीघाट – पश्चिम बंगाल","बसोहली – जम्मू और कश्मीर","किशनगढ़ – गुजरात"],"explanationHi":"बनी ठनी चित्र के लिए प्रसिद्ध किशनगढ़ राजस्थानी शैली है। अन्य तीन युग्म सही हैं।"},
  {"id":"history-art-culture-29","question":"How many of these are on UNESCO’s list of the Intangible Cultural Heritage of Humanity? Kumbh Mela, Yoga, Garba of Gujarat, Ramlila","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four: Ramlila (2008), Yoga (2016), Kumbh Mela (2017) and Garba (2023).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने यूनेस्को की मानवता की अमूर्त सांस्कृतिक विरासत की सूची में हैं? कुंभ मेला, योग, गुजरात का गरबा, रामलीला","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार: रामलीला (2008), योग (2016), कुंभ मेला (2017) और गरबा (2023)।"},
  {"id":"history-art-culture-30","question":"Assertion (A): Gandhara art shows strong Greco-Roman influence. Reason (R): It developed in the north-west, a region in long contact with Hellenistic and Roman culture.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: Gandhara’s position on the routes linking India with the Hellenistic and Roman world gave its Buddha images their wavy hair and toga-like robes.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): गांधार कला पर ग्रीको-रोमन प्रभाव स्पष्ट है। कारण (R): यह उत्तर-पश्चिम में विकसित हुई, जो क्षेत्र यूनानी और रोमन संस्कृति के लंबे संपर्क में रहा।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है, लेकिन R गलत है","A गलत है, लेकिन R सही है"],"explanationHi":"दोनों सही हैं और R, A की व्याख्या करता है: भारत को यूनानी और रोमन जगत से जोड़ने वाले मार्गों पर गांधार की स्थिति ने इसकी बुद्ध मूर्तियों को लहरदार बाल और टोगा जैसे वस्त्र दिए।"},
  {"id":"history-art-culture-31","question":"Assertion (A): The temples of Khajuraho are built in the Nagara style. Reason (R): They were built by the Pallava rulers.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A is true: Khajuraho temples have curvilinear shikharas of the Nagara style. R is false: they were built by the Chandelas; the Pallavas ruled in Tamil Nadu.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): खजुराहो के मंदिर नागर शैली में बने हैं। कारण (R): इन्हें पल्लव शासकों ने बनवाया था।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है, लेकिन R गलत है","A गलत है, लेकिन R सही है"],"explanationHi":"A सही है: खजुराहो के मंदिरों में नागर शैली के वक्ररेखीय शिखर हैं। R गलत है: इन्हें चंदेलों ने बनवाया था; पल्लवों ने तमिलनाडु में शासन किया।"},
  {"id":"history-art-culture-32","question":"Which pair of musician and instrument is NOT correctly matched?","options":["Bismillah Khan – Shehnai","Hariprasad Chaurasia – Flute","Zakir Hussain – Tabla","Amjad Ali Khan – Santoor"],"answer":3,"explanation":"Amjad Ali Khan plays the sarod; the santoor is associated with Shivkumar Sharma.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"संगीतकार और वाद्य यंत्र का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["बिस्मिल्लाह खान – शहनाई","हरिप्रसाद चौरसिया – बाँसुरी","ज़ाकिर हुसैन – तबला","अमजद अली खान – संतूर"],"explanationHi":"अमजद अली खान सरोद बजाते हैं; संतूर शिवकुमार शर्मा से जुड़ा है।"},
  {"id":"history-art-culture-33","question":"Arrange these works in chronological order: 1. Kalhana’s Rajatarangini 2. Bihari’s Satsai 3. Kalidasa’s Abhijnanashakuntalam 4. Banabhatta’s Harshacharita","options":["3-4-1-2","4-3-1-2","3-1-4-2","3-4-2-1"],"answer":0,"explanation":"Kalidasa (Gupta age, about 4th–5th century), Banabhatta (7th century, court of Harsha), Kalhana (1148–49), Bihari’s Satsai (17th century).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन रचनाओं को कालक्रम के अनुसार व्यवस्थित कीजिए: 1. कल्हण की राजतरंगिणी 2. बिहारी की सतसई 3. कालिदास का अभिज्ञानशाकुंतलम् 4. बाणभट्ट का हर्षचरित","optionsHi":["3-4-1-2","4-3-1-2","3-1-4-2","3-4-2-1"],"explanationHi":"कालिदास (गुप्त काल, लगभग चौथी-5वीं शताब्दी), बाणभट्ट (7वीं शताब्दी, हर्ष का दरबार), कल्हण (1148-49), बिहारी की सतसई (17वीं शताब्दी)।"},
  {"id":"history-art-culture-34","question":"How many of these statements about Hindu temple architecture are correct? I. The garbhagriha houses the main deity. II. The amalaka is the entrance gateway of a Nagara temple. III. The shikhara is typical of the Nagara style and the vimana of the Dravida style. IV. The gopuram is the main tower over the sanctum of a Dravida temple.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. The amalaka is the ribbed stone disc on top of a Nagara shikhara, and the gopuram is the gateway tower; the tower over the sanctum is the vimana.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"हिंदू मंदिर स्थापत्य के बारे में इनमें से कितने कथन सही हैं? I. गर्भगृह में मुख्य देवता विराजमान होते हैं। II. आमलक नागर मंदिर का प्रवेश द्वार है। III. शिखर नागर शैली की और विमान द्रविड़ शैली की विशेषता है। IV. गोपुरम द्रविड़ मंदिर में गर्भगृह के ऊपर का मुख्य शिखर है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। आमलक नागर शिखर के शीर्ष पर बनी धारीदार पत्थर की चकती है, और गोपुरम प्रवेश-द्वार का शिखर है; गर्भगृह के ऊपर का शिखर विमान है।"},
  {"id":"history-art-culture-35","question":"Match the festival with its state: A. Chapchar Kut B. Wangala C. Nuakhai D. Losoong — 1. Meghalaya 2. Mizoram 3. Sikkim 4. Odisha","options":["A-2, B-1, C-3, D-4","A-2, B-1, C-4, D-3","A-1, B-2, C-4, D-3","A-2, B-4, C-1, D-3"],"answer":1,"explanation":"Chapchar Kut – Mizoram; Wangala (Garo harvest festival) – Meghalaya; Nuakhai (new rice) – Odisha; Losoong (Bhutia new year) – Sikkim.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"त्योहार का उसके राज्य से मिलान कीजिए: A. चापचर कुट B. वांगला C. नुआखाई D. लोसूंग — 1. मेघालय 2. मिज़ोरम 3. सिक्किम 4. ओडिशा","optionsHi":["A-2, B-1, C-3, D-4","A-2, B-1, C-4, D-3","A-1, B-2, C-4, D-3","A-2, B-4, C-1, D-3"],"explanationHi":"चापचर कुट – मिज़ोरम; वांगला (गारो फसल उत्सव) – मेघालय; नुआखाई (नया चावल) – ओडिशा; लोसूंग (भूटिया नववर्ष) – सिक्किम।"},
  {"id":"history-art-culture-36","question":"Which one of the following is NOT a UNESCO World Heritage Site?","options":["Ramappa Temple, Telangana","Dholavira, Gujarat","Santiniketan, West Bengal","Golden Temple, Amritsar"],"answer":3,"explanation":"Ramappa and Dholavira were inscribed in 2021 and Santiniketan in 2023. The Golden Temple is not on the World Heritage List.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन यूनेस्को का विश्व धरोहर स्थल नहीं है?","optionsHi":["रामप्पा मंदिर, तेलंगाना","धोलावीरा, गुजरात","शांतिनिकेतन, पश्चिम बंगाल","स्वर्ण मंदिर, अमृतसर"],"explanationHi":"रामप्पा और धोलावीरा 2021 में तथा शांतिनिकेतन 2023 में सूची में शामिल हुए। स्वर्ण मंदिर विश्व धरोहर सूची में नहीं है।"},
  {"id":"history-art-culture-37","question":"How many of these statements are correct? I. Raga and tala are basic elements of both Hindustani and Carnatic music. II. Tyagaraja composed mainly in Kannada. III. Purandaradasa is called the father (Pitamaha) of Carnatic music. IV. Thumri is a form of Carnatic music.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. Tyagaraja composed mainly in Telugu, and Thumri is a light-classical form of Hindustani music.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. राग और ताल हिंदुस्तानी और कर्नाटक दोनों संगीत के मूल तत्व हैं। II. त्यागराज ने मुख्यतः कन्नड़ में रचनाएँ कीं। III. पुरंदरदास को कर्नाटक संगीत का पितामह कहा जाता है। IV. ठुमरी कर्नाटक संगीत का एक रूप है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। त्यागराज ने मुख्यतः तेलुगु में रचनाएँ कीं, और ठुमरी हिंदुस्तानी संगीत का सुगम-शास्त्रीय रूप है।"},
  {"id":"history-art-culture-38","question":"Assertion (A): Kathakali performers wear elaborate face make-up and costumes. Reason (R): Kathakali originated in Kerala.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but R does not explain A: the make-up identifies character types (pacha for noble heroes, kathi for villains), which has nothing to do with the region of origin.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): कथकली कलाकार विस्तृत मुख-सज्जा और वेशभूषा धारण करते हैं। कारण (R): कथकली की उत्पत्ति केरल में हुई।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है, लेकिन R गलत है","A गलत है, लेकिन R सही है"],"explanationHi":"दोनों सही हैं, लेकिन R, A की व्याख्या नहीं करता: मुख-सज्जा पात्रों के प्रकार (कुलीन नायकों के लिए पच्चा, खलनायकों के लिए कत्ती) बताती है, जिसका उत्पत्ति-क्षेत्र से कोई संबंध नहीं।"},
  {"id":"history-art-culture-39","question":"Arrange these temples by when they were built: 1. Chennakeshava temple, Belur 2. Brihadeeswara temple, Thanjavur 3. Sun Temple, Konark 4. Vittala temple, Hampi","options":["2-1-4-3","1-2-3-4","2-1-3-4","2-3-1-4"],"answer":2,"explanation":"Brihadeeswara completed 1010 (Rajaraja I), Chennakeshava 1117 (Hoysala Vishnuvardhana), Konark about 1250 (Narasimhadeva I), Vittala temple 15th–16th century (Vijayanagara).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन मंदिरों को उनके निर्माण के समय के अनुसार व्यवस्थित कीजिए: 1. चेन्नाकेशव मंदिर, बेलूर 2. बृहदीश्वर मंदिर, तंजावुर 3. सूर्य मंदिर, कोणार्क 4. विट्ठल मंदिर, हम्पी","optionsHi":["2-1-4-3","1-2-3-4","2-1-3-4","2-3-1-4"],"explanationHi":"बृहदीश्वर 1010 में पूर्ण (राजराज प्रथम), चेन्नाकेशव 1117 (होयसल विष्णुवर्धन), कोणार्क लगभग 1250 (नरसिंहदेव प्रथम), विट्ठल मंदिर 15वीं-16वीं शताब्दी (विजयनगर)।"},
  {"id":"history-art-culture-40","question":"Which pair of temple and the dynasty that built it is NOT correctly matched?","options":["Brihadeeswara, Thanjavur – Cholas","Kailasa, Ellora – Rashtrakutas","Shore Temple, Mamallapuram – Pallavas","Lingaraja, Bhubaneswar – Chandelas"],"answer":3,"explanation":"The Lingaraja temple was built by the Somavamshi kings of Odisha in the 11th century; the Chandelas built Khajuraho.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मंदिर और उसे बनवाने वाले राजवंश का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["बृहदीश्वर, तंजावुर – चोल","कैलास, एलोरा – राष्ट्रकूट","तट मंदिर, महाबलीपुरम – पल्लव","लिंगराज, भुवनेश्वर – चंदेल"],"explanationHi":"लिंगराज मंदिर 11वीं शताब्दी में ओडिशा के सोमवंशी राजाओं ने बनवाया था; चंदेलों ने खजुराहो बनवाया।"},
  {"id":"history-art-culture-41","question":"Bharatanatyam, one of the oldest classical dance forms, developed in:","options":["Kerala","Tamil Nadu","Karnataka","Andhra Pradesh"],"answer":1,"explanation":"Bharatanatyam grew from the temple dance (sadir) of Tamil Nadu. Kerala's classical dances are Kathakali and Mohiniyattam, and Andhra Pradesh's is Kuchipudi.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"सबसे प्राचीन शास्त्रीय नृत्य रूपों में से एक भरतनाट्यम का विकास कहाँ हुआ?","optionsHi":["केरल","तमिलनाडु","कर्नाटक","आंध्र प्रदेश"],"explanationHi":"भरतनाट्यम तमिलनाडु के मंदिर नृत्य (सादिर) से विकसित हुआ। केरल के शास्त्रीय नृत्य कथकली और मोहिनीअट्टम हैं, और आंध्र प्रदेश का कुचिपुड़ी है।"},
  {"id":"history-art-culture-42","question":"Bhangra is a folk dance of:","options":["Haryana","Gujarat","Punjab","Rajasthan"],"answer":2,"explanation":"Bhangra is the harvest dance of Punjab, performed to the dhol around Baisakhi. Giddha is the women's folk dance of the same region.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"भांगड़ा किस राज्य का लोक नृत्य है?","optionsHi":["हरियाणा","गुजरात","पंजाब","राजस्थान"],"explanationHi":"भांगड़ा पंजाब का फसल नृत्य है, जो बैसाखी के आसपास ढोल की थाप पर किया जाता है। गिद्धा इसी क्षेत्र का महिलाओं का लोक नृत्य है।"},
  {"id":"history-art-culture-43","question":"The Taj Mahal at Agra was built by:","options":["Akbar","Jahangir","Aurangzeb Alamgir","Shah Jahan"],"answer":3,"explanation":"Shah Jahan built the Taj Mahal (1632–53) as the tomb of his wife Mumtaz Mahal. It was inscribed as a World Heritage Site in 1983.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"आगरा का ताजमहल किसने बनवाया था?","optionsHi":["अकबर","जहाँगीर","औरंगजेब आलमगीर","शाहजहाँ"],"explanationHi":"शाहजहाँ ने अपनी पत्नी मुमताज महल के मकबरे के रूप में ताजमहल (1632-53) बनवाया। इसे 1983 में विश्व धरोहर स्थल घोषित किया गया।"},
  {"id":"history-art-culture-44","question":"The Kumbh Mela is held in rotation at Prayagraj, Haridwar, Ujjain and:","options":["Nashik","Varanasi","Puri","Mathura"],"answer":0,"explanation":"The four Kumbh sites are Prayagraj (Ganga–Yamuna), Haridwar (Ganga), Ujjain (Shipra) and Nashik (Godavari).","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"कुंभ मेला प्रयागराज, हरिद्वार, उज्जैन और किस स्थान पर बारी-बारी से आयोजित होता है?","optionsHi":["नासिक","वाराणसी","पुरी","मथुरा"],"explanationHi":"कुंभ के चार स्थल हैं: प्रयागराज (गंगा-यमुना), हरिद्वार (गंगा), उज्जैन (शिप्रा) और नासिक (गोदावरी)।"},
  {"id":"history-art-culture-45","question":"Pongal, the harvest festival, is mainly celebrated in:","options":["Punjab","Tamil Nadu","Assam","West Bengal"],"answer":1,"explanation":"Pongal is Tamil Nadu's four-day harvest festival in mid-January, at the same time as Makar Sankranti, Lohri in Punjab, Magh Bihu in Assam and Poush Parbon in Bengal.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"फसल का त्योहार पोंगल मुख्यतः कहाँ मनाया जाता है?","optionsHi":["पंजाब","तमिलनाडु","असम","पश्चिम बंगाल"],"explanationHi":"पोंगल तमिलनाडु का चार दिवसीय फसल त्योहार है, जो मकर संक्रांति के साथ जनवरी के मध्य में मनाया जाता है; इसी समय पंजाब में लोहड़ी, असम में माघ बिहू और बंगाल में पौष पार्बण होता है।"},
  {"id":"history-art-culture-46","question":"The Ras Lila, depicting Krishna's dance with the gopis, is a central theme of which classical dance?","options":["Kathak","Manipuri","Kuchipudi","Sattriya"],"answer":1,"explanation":"Manipuri dance, with its gentle movements and Vaishnava themes, is famous for its Ras Lila. Kathak also uses Krishna stories, but the Ras Lila is the signature of Manipuri.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"गोपियों के साथ कृष्ण के नृत्य को दर्शाने वाली रास लीला किस शास्त्रीय नृत्य का केंद्रीय विषय है?","optionsHi":["कथक","मणिपुरी","कुचिपुड़ी","सत्रीया"],"explanationHi":"कोमल गतियों और वैष्णव विषयों वाला मणिपुरी नृत्य अपनी रास लीला के लिए प्रसिद्ध है। कथक में भी कृष्ण की कथाएँ होती हैं, पर रास लीला मणिपुरी की पहचान है।"},
  {"id":"history-art-culture-47","question":"Gond painting, made of dots and fine lines, is a tribal art chiefly of:","options":["Madhya Pradesh","Bihar (Mithila region)","Maharashtra (Thane district)","Odisha"],"answer":0,"explanation":"Gond art comes from the Gond tribe of Madhya Pradesh; Jangarh Singh Shyam made it widely known. Warli is from Maharashtra and Madhubani from Bihar.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"बिंदुओं और बारीक रेखाओं से बनी गोंड चित्रकला मुख्यतः किस राज्य की जनजातीय कला है?","optionsHi":["मध्य प्रदेश","बिहार (मिथिला क्षेत्र)","महाराष्ट्र (ठाणे जिला)","ओडिशा"],"explanationHi":"गोंड कला मध्य प्रदेश की गोंड जनजाति की है; जनगढ़ सिंह श्याम ने इसे व्यापक रूप से प्रसिद्ध किया। वारली महाराष्ट्र की और मधुबनी बिहार की है।"},
  {"id":"history-art-culture-48","question":"Phad painting, long cloth scrolls narrating the lives of folk deities such as Pabuji and Devnarayan, belongs to:","options":["Gujarat","Rajasthan","Odisha","Andhra Pradesh"],"answer":1,"explanation":"Phad is a scroll painting of Rajasthan (Shahpura, Bhilwara), carried by bhopa priests who sing the story as they show the scroll.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"पाबूजी और देवनारायण जैसे लोक देवताओं के जीवन का वर्णन करने वाली कपड़े की लंबी पटचित्र फड़ चित्रकला किससे संबंधित है?","optionsHi":["गुजरात","राजस्थान","ओडिशा","आंध्र प्रदेश"],"explanationHi":"फड़ राजस्थान (शाहपुरा, भीलवाड़ा) की पटचित्र कला है, जिसे भोपा पुजारी लेकर चलते हैं और पटचित्र दिखाते हुए कथा गाते हैं।"},
  {"id":"history-art-culture-49","question":"Tanjore painting, known for its rich colours and use of gold foil and semi-precious stones, is from:","options":["Kerala","Karnataka","Tamil Nadu","Andhra Pradesh"],"answer":2,"explanation":"Thanjavur painting flourished under the Marathas of Thanjavur in Tamil Nadu. Mysore painting of Karnataka uses gesso work more delicately.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"समृद्ध रंगों तथा स्वर्ण पत्र और अर्ध-कीमती पत्थरों के प्रयोग के लिए प्रसिद्ध तंजौर चित्रकला किस राज्य की है?","optionsHi":["केरल","कर्नाटक","तमिलनाडु","आंध्र प्रदेश"],"explanationHi":"तंजावुर चित्रकला तमिलनाडु में तंजावुर के मराठों के अधीन फली-फूली। कर्नाटक की मैसूर चित्रकला में गेसो का काम अधिक नाजुक होता है।"},
  {"id":"history-art-culture-50","question":"Akbar built the Buland Darwaza at Fatehpur Sikri to commemorate his victory over:","options":["Bengal","Gujarat","Chittor","Kabul"],"answer":1,"explanation":"The Buland Darwaza commemorates Akbar's conquest of Gujarat (1573). It is the main gateway of the Jama Masjid at Fatehpur Sikri.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"अकबर ने फतेहपुर सीकरी में बुलंद दरवाजा किस पर अपनी विजय की स्मृति में बनवाया?","optionsHi":["बंगाल","गुजरात","चित्तौड़","काबुल"],"explanationHi":"बुलंद दरवाजा अकबर की गुजरात विजय (1573) का स्मारक है। यह फतेहपुर सीकरी की जामा मस्जिद का मुख्य प्रवेश द्वार है।"},
  {"id":"history-art-culture-51","question":"The 'kriti' is a composition form chiefly associated with:","options":["Hindustani music","Carnatic music","Sufi qawwali","Rabindra Sangeet"],"answer":1,"explanation":"The kriti, with its pallavi, anupallavi and charanam, is the main concert form of Carnatic music, perfected by the Trinity. Khayal and dhrupad are Hindustani forms.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"'कृति' रचना-रूप मुख्यतः किससे संबंधित है?","optionsHi":["हिंदुस्तानी संगीत","कर्नाटक संगीत","सूफी कव्वाली","रवींद्र संगीत"],"explanationHi":"पल्लवी, अनुपल्लवी और चरणम् वाली कृति कर्नाटक संगीत का मुख्य कार्यक्रम-रूप है, जिसे त्रिमूर्ति ने पूर्णता दी। ख़याल और ध्रुपद हिंदुस्तानी रूप हैं।"},
  {"id":"history-art-culture-52","question":"The Elephanta caves, known for the colossal three-headed Sadashiva (Trimurti), are near:","options":["Aurangabad","Pune","Mumbai","Nashik"],"answer":2,"explanation":"The Elephanta caves are on Gharapuri island in Mumbai harbour. Ajanta and Ellora are near Aurangabad.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"विशाल तीन मुख वाली सदाशिव (त्रिमूर्ति) प्रतिमा के लिए प्रसिद्ध एलिफेंटा की गुफाएँ किसके पास हैं?","optionsHi":["औरंगाबाद","पुणे","मुंबई","नासिक"],"explanationHi":"एलिफेंटा की गुफाएँ मुंबई बंदरगाह में घारापुरी द्वीप पर हैं। अजंता और एलोरा औरंगाबाद के पास हैं।"},
  {"id":"history-art-culture-53","question":"Thrissur Pooram, a temple festival known for its caparisoned elephants and percussion, is celebrated in:","options":["Karnataka","Tamil Nadu","Kerala","Goa"],"answer":2,"explanation":"Thrissur Pooram is held at the Vadakkunnathan temple in Thrissur, Kerala; it was started by Sakthan Thampuran, ruler of Cochin.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"सजे-धजे हाथियों और वाद्य-वृंद के लिए प्रसिद्ध मंदिर उत्सव त्रिशूर पूरम कहाँ मनाया जाता है?","optionsHi":["कर्नाटक","तमिलनाडु","केरल","गोवा"],"explanationHi":"त्रिशूर पूरम केरल के त्रिशूर में वडक्कुनाथन मंदिर में मनाया जाता है; इसे कोचीन के शासक शक्तन तंपुरान ने आरंभ किया था।"},
  {"id":"history-art-culture-54","question":"The invention of the sitar is traditionally attributed to:","options":["Tansen","Amir Khusrau","Baiju Bawra","Swami Haridas"],"answer":1,"explanation":"Tradition credits Amir Khusrau (13th–14th century) with the sitar and the tabla, though historians think the sitar took its modern form later. Tansen is linked with dhrupad.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"सितार के आविष्कार का श्रेय परंपरागत रूप से किसे दिया जाता है?","optionsHi":["तानसेन","अमीर खुसरो","बैजू बावरा","स्वामी हरिदास"],"explanationHi":"परंपरा सितार और तबले का श्रेय अमीर खुसरो (13वीं-14वीं शताब्दी) को देती है, यद्यपि इतिहासकार मानते हैं कि सितार ने अपना आधुनिक रूप बाद में लिया। तानसेन का संबंध ध्रुपद से है।"},
  {"id":"history-art-culture-55","question":"The Mughal painter Ustad Mansur, given the title Nadir-ul-Asr by Jahangir, is best known for:","options":["Portraits of the emperor at court","Studies of birds and animals","Illustrations of the Hamzanama","Battle scenes of the Akbarnama"],"answer":1,"explanation":"Mansur's studies of the Siberian crane, zebra, turkey cock and tulips reflect Jahangir's interest in natural history. The Hamzanama was illustrated earlier, under Akbar.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जहाँगीर द्वारा 'नादिर-उल-अस्र' की उपाधि पाने वाले मुगल चित्रकार उस्ताद मंसूर किसके लिए सबसे प्रसिद्ध हैं?","optionsHi":["दरबार में सम्राट के व्यक्ति-चित्र","पक्षियों और पशुओं के अध्ययन-चित्र","हम्ज़ानामा के चित्रण","अकबरनामा के युद्ध दृश्य"],"explanationHi":"साइबेरियाई सारस, ज़ेबरा, टर्की मुर्गे और ट्यूलिप के मंसूर के अध्ययन-चित्र जहाँगीर की प्राकृतिक इतिहास में रुचि को दर्शाते हैं। हम्ज़ानामा का चित्रण इससे पहले, अकबर के काल में हुआ था।"},
  {"id":"history-art-culture-56","question":"The Hamzanama, a huge illustrated manuscript of the adventures of Amir Hamza, was produced under:","options":["Babur","Humayun","Akbar","Shah Jahan"],"answer":2,"explanation":"The Hamzanama (about 1,400 large paintings) was made in Akbar's atelier under Mir Sayyid Ali and Abd-us-Samad, who had come with Humayun from Persia.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अमीर हम्ज़ा के साहसिक कारनामों की विशाल सचित्र पांडुलिपि हम्ज़ानामा किसके शासनकाल में तैयार हुई?","optionsHi":["बाबर","हुमायूँ","अकबर","शाहजहाँ"],"explanationHi":"हम्ज़ानामा (लगभग 1,400 बड़े चित्र) अकबर के चित्रशाला में मीर सैयद अली और अब्दुस्समद के निर्देशन में बना, जो हुमायूँ के साथ फारस से आए थे।"},
  {"id":"history-art-culture-57","question":"Basohli painting, with bold colours and beetle-wing decoration, is an early school of:","options":["Rajasthani painting","Pahari painting","Deccani painting","Mughal painting"],"answer":1,"explanation":"Basohli (in Kathua district of Jammu and Kashmir) is one of the earliest Pahari schools; Guler and Kangra developed later in the same hills.","difficulty":"hard","source":"UPSC Prelims","questionHi":"चटक रंगों और भृंग-पंख सजावट वाली बसोहली चित्रकला किस शैली की आरंभिक शाखा है?","optionsHi":["राजस्थानी चित्रकला","पहाड़ी चित्रकला","दक्कनी चित्रकला","मुगल चित्रकला"],"explanationHi":"बसोहली (जम्मू और कश्मीर के कठुआ जिले में) सबसे आरंभिक पहाड़ी शैलियों में से एक है; गुलेर और कांगड़ा इन्हीं पहाड़ियों में बाद में विकसित हुईं।"},
  {"id":"history-art-culture-58","question":"'Bani Thani', called the 'Mona Lisa of India', is a masterpiece of which school of painting?","options":["Kishangarh","Mewar (Udaipur)","Bundi-Kota","Kangra (Pahari)"],"answer":0,"explanation":"Bani Thani was painted by Nihal Chand at Kishangarh under Raja Sawant Singh around 1750; the school is known for its elongated faces and almond eyes.","difficulty":"hard","source":"UPSC Prelims","questionHi":"'भारत की मोनालिसा' कही जाने वाली 'बनी ठनी' किस चित्रकला शैली की उत्कृष्ट कृति है?","optionsHi":["किशनगढ़","मेवाड़ (उदयपुर)","बूँदी-कोटा","कांगड़ा (पहाड़ी)"],"explanationHi":"बनी ठनी को निहाल चंद ने लगभग 1750 में किशनगढ़ में राजा सावंत सिंह के अधीन चित्रित किया; यह शैली लंबे चेहरों और बादाम जैसी आँखों के लिए जानी जाती है।"},
  {"id":"history-art-culture-59","question":"Mudiyettu, a ritual dance-drama on the battle between goddess Kali and the demon Darika, is on UNESCO's Intangible Heritage list. It belongs to:","options":["Kerala","Karnataka","Tamil Nadu","Odisha"],"answer":0,"explanation":"Mudiyettu of Kerala was inscribed in 2010. Kerala's Kutiyattam was inscribed earlier, among the first proclamations of 2001.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"देवी काली और राक्षस दारिक के बीच युद्ध पर आधारित अनुष्ठानिक नृत्य-नाटिका मुदियेट्टु यूनेस्को की अमूर्त विरासत सूची में है। यह किससे संबंधित है?","optionsHi":["केरल","कर्नाटक","तमिलनाडु","ओडिशा"],"explanationHi":"केरल का मुदियेट्टु 2010 में सूची में शामिल हुआ। केरल का कुटियाट्टम इससे पहले 2001 की आरंभिक घोषणाओं में शामिल हुआ था।"},
  {"id":"history-art-culture-60","question":"Most of the polished Ashokan pillars were carved from sandstone quarried at:","options":["Mathura","Chunar","Sanchi","Amaravati"],"answer":1,"explanation":"The Mauryan pillars were made of buff Chunar sandstone (near Varanasi) and given a mirror-like polish. Mathura's red sandstone was used later by the Kushana sculptors.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अधिकांश चमकदार अशोक स्तंभ किस स्थान से निकाले गए बलुआ पत्थर से तराशे गए थे?","optionsHi":["मथुरा","चुनार","साँची","अमरावती"],"explanationHi":"मौर्य स्तंभ चुनार (वाराणसी के पास) के पीले-भूरे बलुआ पत्थर से बने थे और उन पर दर्पण जैसी पॉलिश की गई थी। मथुरा का लाल बलुआ पत्थर बाद में कुषाण मूर्तिकारों ने प्रयोग किया।"},
  {"id":"history-art-culture-61","question":"The Mathura school of sculpture typically used:","options":["Grey-blue schist","White Amaravati limestone","Spotted red sandstone","Buff Chunar sandstone"],"answer":2,"explanation":"Mathura sculptors used spotted red sandstone. Grey schist is typical of Gandhara and white limestone (often called marble) of Amaravati; polished buff Chunar sandstone belongs to the Mauryan pillars.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मथुरा शैली की मूर्तिकला में सामान्यतः किसका प्रयोग होता था?","optionsHi":["धूसर-नीला शिस्ट","अमरावती का सफेद चूना पत्थर","चित्तीदार लाल बलुआ पत्थर","पीला-भूरा चुनार बलुआ पत्थर"],"explanationHi":"मथुरा के मूर्तिकार चित्तीदार लाल बलुआ पत्थर का प्रयोग करते थे। धूसर शिस्ट गांधार की और सफेद चूना पत्थर (प्रायः संगमरमर कहा जाता है) अमरावती की विशेषता है; पॉलिश किया हुआ पीला-भूरा चुनार बलुआ पत्थर मौर्य स्तंभों का है।"},
  {"id":"history-art-culture-62","question":"The Amaravati school of sculpture flourished mainly under the patronage of the:","options":["Kushanas and Western Kshatrapas","Guptas and Vakatakas","Satavahanas and Ikshvakus","Pallavas and Cholas"],"answer":2,"explanation":"Amaravati in the Krishna valley flourished under the Satavahanas and later the Ikshvakus; its narrative reliefs in white limestone are noted for movement.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अमरावती शैली की मूर्तिकला मुख्यतः किनके संरक्षण में फली-फूली?","optionsHi":["कुषाण और पश्चिमी क्षत्रप","गुप्त और वाकाटक","सातवाहन और इक्ष्वाकु","पल्लव और चोल"],"explanationHi":"कृष्णा घाटी में अमरावती सातवाहनों और बाद में इक्ष्वाकुओं के अधीन फली-फूली; सफेद चूना पत्थर पर इसके कथात्मक उत्कीर्ण दृश्य गति के लिए प्रसिद्ध हैं।"},
  {"id":"history-art-culture-63","question":"The richly carved Hoysala temples at Belur and Halebidu are built mainly of:","options":["Granite","Soapstone","Red sandstone","Laterite"],"answer":1,"explanation":"Soft soapstone (chloritic schist) allowed the Hoysala craftsmen to carve extremely fine detail, and it hardens on exposure to air. Granite, the usual southern stone, is too hard for such lacework.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बेलूर और हलेबीडु के अलंकृत होयसल मंदिर मुख्यतः किससे बने हैं?","optionsHi":["ग्रेनाइट","सोपस्टोन (संगमरमर जैसा मुलायम पत्थर)","लाल बलुआ पत्थर","लैटेराइट"],"explanationHi":"मुलायम सोपस्टोन (क्लोराइटिक शिस्ट) से होयसल कारीगर अत्यंत बारीक नक्काशी कर पाए, और हवा के संपर्क में यह कठोर हो जाता है। दक्षिण का सामान्य पत्थर ग्रेनाइट ऐसी जालीदार नक्काशी के लिए बहुत कठोर है।"},
  {"id":"history-art-culture-64","question":"The Jantar Mantar observatories at Delhi, Jaipur, Ujjain, Varanasi and Mathura were built by:","options":["Raja Man Singh","Sawai Jai Singh II","Maharaja Ranjit Singh","Raja Todar Mal"],"answer":1,"explanation":"Sawai Jai Singh II of Amber, founder of Jaipur, built the five observatories in the early 18th century. The Jaipur Jantar Mantar is a World Heritage Site.","difficulty":"hard","source":"SSC CGL · State PSCs","questionHi":"दिल्ली, जयपुर, उज्जैन, वाराणसी और मथुरा की जंतर मंतर वेधशालाएँ किसने बनवाईं?","optionsHi":["राजा मान सिंह","सवाई जय सिंह द्वितीय","महाराजा रणजीत सिंह","राजा टोडरमल"],"explanationHi":"आमेर के सवाई जय सिंह द्वितीय ने, जो जयपुर के संस्थापक थे, 18वीं शताब्दी के आरंभ में पाँचों वेधशालाएँ बनवाईं। जयपुर का जंतर मंतर विश्व धरोहर स्थल है।"},
  {"id":"history-art-culture-65","question":"Kalbelia, the folk dance and song form inscribed by UNESCO in 2010, is associated with:","options":["Snake charmers of Rajasthan","Fisherfolk of the Konkan coast","Tea-garden workers of Assam","Tribal hunters of Odisha"],"answer":0,"explanation":"The Kalbelias were traditionally snake charmers; their swirling black costumes recall a serpent. Ghoomar is a different Rajasthani dance.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"2010 में यूनेस्को द्वारा सूचीबद्ध लोक नृत्य और गीत रूप कालबेलिया किससे संबंधित है?","optionsHi":["राजस्थान के सपेरे","कोंकण तट के मछुआरे","असम के चाय-बागान श्रमिक","ओडिशा के आदिवासी शिकारी"],"explanationHi":"कालबेलिया परंपरागत रूप से सपेरे थे; उनकी घूमती काली पोशाकें साँप की याद दिलाती हैं। घूमर राजस्थान का एक अलग नृत्य है।"},
  {"id":"history-art-culture-66","question":"The charbagh (four-part) garden layout was first used on a grand scale for a mausoleum in India at:","options":["Taj Mahal","Tomb of Itimad-ud-Daulah","Humayun's Tomb","Akbar's tomb at Sikandra"],"answer":2,"explanation":"Humayun's Tomb (1565–72), built by his widow Bega Begum, was the first great garden-tomb of the subcontinent and a model for the Taj Mahal.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत में किसी मकबरे के लिए चारबाग (चार भागों वाले) उद्यान का विन्यास पहली बार बड़े पैमाने पर कहाँ प्रयोग किया गया?","optionsHi":["ताजमहल","इतमादुद्दौला का मकबरा","हुमायूँ का मकबरा","सिकंदरा में अकबर का मकबरा"],"explanationHi":"हुमायूँ का मकबरा (1565-72), जिसे उनकी विधवा बेगा बेगम ने बनवाया, उपमहाद्वीप का पहला महान उद्यान-मकबरा था और ताजमहल के लिए आदर्श बना।"},
  {"id":"history-art-culture-67","question":"The Mughal building where pietra dura (inlay of semi-precious stones in marble) was first used extensively is:","options":["Humayun's Tomb, Delhi","Tomb of Itimad-ud-Daulah, Agra","Buland Darwaza, Fatehpur Sikri","Jahangir's Tomb, Lahore"],"answer":1,"explanation":"Nur Jahan's tomb for her father Itimad-ud-Daulah (1622–28), the 'Baby Taj', marks the change from red sandstone to white marble with pietra dura.","difficulty":"hard","source":"UPSC Prelims","questionHi":"वह मुगल इमारत कौन-सी है जहाँ संगमरमर में अर्ध-कीमती पत्थरों की जड़ाई (पिएत्रा दुरा) का पहली बार व्यापक प्रयोग हुआ?","optionsHi":["हुमायूँ का मकबरा, दिल्ली","इतमादुद्दौला का मकबरा, आगरा","बुलंद दरवाजा, फतेहपुर सीकरी","जहाँगीर का मकबरा, लाहौर"],"explanationHi":"नूरजहाँ द्वारा अपने पिता इतमादुद्दौला के लिए बनवाया गया मकबरा (1622-28), 'बेबी ताज', लाल बलुआ पत्थर से सफेद संगमरमर और पिएत्रा दुरा की ओर परिवर्तन का सूचक है।"},
  {"id":"history-art-culture-68","question":"Match the folk dance with its state: A. Lavani B. Dollu Kunitha C. Bihu D. Ghoomar — 1. Rajasthan 2. Assam 3. Karnataka 4. Maharashtra","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Lavani – Maharashtra; Dollu Kunitha (drum dance of the Kurubas) – Karnataka; Bihu – Assam; Ghoomar – Rajasthan.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"लोक नृत्य का उसके राज्य से मिलान कीजिए: A. लावणी B. डोल्लू कुनिथा C. बिहू D. घूमर — 1. राजस्थान 2. असम 3. कर्नाटक 4. महाराष्ट्र","optionsHi":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"लावणी – महाराष्ट्र; डोल्लू कुनिथा (कुरुबा समुदाय का ढोल नृत्य) – कर्नाटक; बिहू – असम; घूमर – राजस्थान।"},
  {"id":"history-art-culture-69","question":"Match the puppet tradition with its state: A. Kathputli B. Bommalattam C. Tholu Bommalata D. Putul Nach — 1. West Bengal 2. Andhra Pradesh 3. Tamil Nadu 4. Rajasthan","options":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"answer":1,"explanation":"Kathputli (string) – Rajasthan; Bommalattam (string and rod) – Tamil Nadu; Tholu Bommalata (leather shadow) – Andhra Pradesh; Putul Nach (rod) – West Bengal.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कठपुतली परंपरा का उसके राज्य से मिलान कीजिए: A. कठपुतली B. बोम्मलाट्टम C. थोलू बोम्मलाटा D. पुतुल नाच — 1. पश्चिम बंगाल 2. आंध्र प्रदेश 3. तमिलनाडु 4. राजस्थान","optionsHi":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"कठपुतली (धागा) – राजस्थान; बोम्मलाट्टम (धागा और छड़) – तमिलनाडु; थोलू बोम्मलाटा (चमड़े की छाया) – आंध्र प्रदेश; पुतुल नाच (छड़) – पश्चिम बंगाल।"},
  {"id":"history-art-culture-70","question":"Arrange these Mughal buildings by when they were built: 1. Taj Mahal 2. Humayun's Tomb 3. Buland Darwaza 4. Tomb of Itimad-ud-Daulah","options":["2-4-3-1","3-2-4-1","2-3-4-1","2-3-1-4"],"answer":2,"explanation":"Humayun's Tomb 1565–72; Buland Darwaza c. 1575; Itimad-ud-Daulah 1622–28; Taj Mahal 1632–53.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन मुगल इमारतों को उनके निर्माण के समय के अनुसार व्यवस्थित कीजिए: 1. ताजमहल 2. हुमायूँ का मकबरा 3. बुलंद दरवाजा 4. इतमादुद्दौला का मकबरा","optionsHi":["2-4-3-1","3-2-4-1","2-3-4-1","2-3-1-4"],"explanationHi":"हुमायूँ का मकबरा 1565-72; बुलंद दरवाजा लगभग 1575; इतमादुद्दौला 1622-28; ताजमहल 1632-53।"},
  {"id":"history-art-culture-71","question":"How many of these statements about the Ajanta caves are correct? I. They are Buddhist caves. II. Several of the later caves and paintings date from the Vakataka period. III. They are in Odisha. IV. Their paintings mostly show the lives of the Jain Tirthankaras.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. Ajanta is in Maharashtra, and its paintings mostly illustrate the Jataka stories and the life of the Buddha.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अजंता की गुफाओं के बारे में इनमें से कितने कथन सही हैं? I. ये बौद्ध गुफाएँ हैं। II. कई परवर्ती गुफाएँ और चित्र वाकाटक काल के हैं। III. ये ओडिशा में हैं। IV. इनके चित्र अधिकतर जैन तीर्थंकरों के जीवन को दर्शाते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। अजंता महाराष्ट्र में है, और इसके चित्र अधिकतर जातक कथाओं और बुद्ध के जीवन को दर्शाते हैं।"},
  {"id":"history-art-culture-72","question":"Match the Hindustani gharana with the musician most associated with it: A. Kirana B. Gwalior C. Jaipur-Atrauli D. Agra — 1. Alladiya Khan 2. Faiyaz Khan 3. Abdul Karim Khan 4. Haddu and Hassu Khan","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2"],"answer":0,"explanation":"Kirana – Abdul Karim Khan; Gwalior, the oldest khayal gharana – Haddu and Hassu Khan; Jaipur-Atrauli – Alladiya Khan; Agra – Faiyaz Khan ('Aftab-e-Mausiqi').","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"हिंदुस्तानी घराने का उससे सबसे अधिक जुड़े संगीतकार से मिलान कीजिए: A. किराना B. ग्वालियर C. जयपुर-अतरौली D. आगरा — 1. अल्लादिया खान 2. फैयाज खान 3. अब्दुल करीम खान 4. हद्दू और हस्सू खान","optionsHi":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2"],"explanationHi":"किराना – अब्दुल करीम खान; ग्वालियर, सबसे प्राचीन ख़याल घराना – हद्दू और हस्सू खान; जयपुर-अतरौली – अल्लादिया खान; आगरा – फैयाज खान ('आफ़ताब-ए-मौसीक़ी')।"},
  {"id":"history-art-culture-73","question":"Assertion (A): Mughal painting reached its height under Jahangir. Reason (R): Jahangir was a keen connoisseur who claimed he could name the artist of any painting at sight.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: Jahangir's personal taste drove the move to portraiture and natural history, with masters like Abul Hasan, Mansur and Bishandas.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): मुगल चित्रकला जहाँगीर के काल में अपने शिखर पर पहुँची। कारण (R): जहाँगीर एक उत्सुक कला-पारखी थे, जिनका दावा था कि वे किसी भी चित्र के चित्रकार को देखते ही पहचान सकते हैं।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है, लेकिन R गलत है","A गलत है, लेकिन R सही है"],"explanationHi":"दोनों सही हैं और R, A की व्याख्या करता है: जहाँगीर की निजी रुचि ने अबुल हसन, मंसूर और बिशनदास जैसे उस्तादों के साथ व्यक्ति-चित्रण और प्राकृतिक इतिहास की ओर झुकाव को बढ़ावा दिया।"},
  {"id":"history-art-culture-74","question":"Assertion (A): Temples in the Dravida style have tall gateways called gopurams. Reason (R): Temples in the Nagara style have a curvilinear shikhara topped by an amalaka.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both statements are true, but the features of the Nagara style do not explain why Dravida temples have gopurams.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): द्रविड़ शैली के मंदिरों में गोपुरम नामक ऊँचे प्रवेश-द्वार होते हैं। कारण (R): नागर शैली के मंदिरों में वक्ररेखीय शिखर होता है जिसके शीर्ष पर आमलक होता है।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है, लेकिन R गलत है","A गलत है, लेकिन R सही है"],"explanationHi":"दोनों कथन सही हैं, लेकिन नागर शैली की विशेषताएँ यह नहीं समझातीं कि द्रविड़ मंदिरों में गोपुरम क्यों होते हैं।"},
  {"id":"history-art-culture-75","question":"Which pair of dancer and dance form is NOT correctly matched?","options":["Birju Maharaj — Kathak","Kelucharan Mohapatra — Odissi","Kalamandalam Gopi — Manipuri","Guru Bipin Singh — Manipuri"],"answer":2,"explanation":"Kalamandalam Gopi is a Kathakali exponent from Kerala. Guru Bipin Singh is regarded as the father of modern Manipuri dance.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"नर्तक और नृत्य रूप का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["बिरजू महाराज — कथक","केलुचरण महापात्र — ओडिसी","कलामंडलम गोपी — मणिपुरी","गुरु बिपिन सिंह — मणिपुरी"],"explanationHi":"कलामंडलम गोपी केरल के कथकली कलाकार हैं। गुरु बिपिन सिंह को आधुनिक मणिपुरी नृत्य का जनक माना जाता है।"},
  {"id":"history-art-culture-76","question":"How many of these statements about rock-cut architecture are correct? I. Ashoka gave the Barabar caves to the Ajivikas. II. The great chaitya at Karla is in Maharashtra. III. The Udayagiri–Khandagiri caves of Odisha are Jain caves linked with Kharavela. IV. The Elephanta caves are Buddhist.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The Elephanta caves are mainly Shaiva, with the Sadashiva and the Ardhanarishvara panels.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"चट्टान काटकर बनाए गए स्थापत्य के बारे में इनमें से कितने कथन सही हैं? I. अशोक ने बराबर की गुफाएँ आजीविकों को दी थीं। II. कार्ला का विशाल चैत्य महाराष्ट्र में है। III. ओडिशा की उदयगिरि-खंडगिरि गुफाएँ जैन गुफाएँ हैं जो खारवेल से जुड़ी हैं। IV. एलिफेंटा की गुफाएँ बौद्ध हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। एलिफेंटा की गुफाएँ मुख्यतः शैव हैं, जिनमें सदाशिव और अर्धनारीश्वर के फलक हैं।"},
  {"id":"history-art-culture-77","question":"Arrange these temples by when they were built: 1. Lingaraja temple, Bhubaneswar 2. Shore Temple, Mamallapuram 3. Sun Temple, Konark 4. Kailasa temple, Ellora","options":["2-4-3-1","4-2-1-3","2-1-4-3","2-4-1-3"],"answer":3,"explanation":"Shore Temple c. 700–728 (Pallava); Kailasa c. 760s (Rashtrakuta); Lingaraja 11th century (Somavamshi/Ganga); Konark c. 1250 (Eastern Ganga).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन मंदिरों को उनके निर्माण के समय के अनुसार व्यवस्थित कीजिए: 1. लिंगराज मंदिर, भुवनेश्वर 2. तट मंदिर, महाबलीपुरम 3. सूर्य मंदिर, कोणार्क 4. कैलास मंदिर, एलोरा","optionsHi":["2-4-3-1","4-2-1-3","2-1-4-3","2-4-1-3"],"explanationHi":"तट मंदिर लगभग 700-728 (पल्लव); कैलास लगभग 760 के दशक में (राष्ट्रकूट); लिंगराज 11वीं शताब्दी (सोमवंशी/गंग); कोणार्क लगभग 1250 (पूर्वी गंग)।"},
  {"id":"history-art-culture-78","question":"Match the World Heritage Site with its state: A. Group of Monuments at Hampi B. Champaner-Pavagadh C. Manas Wildlife Sanctuary D. Rock Shelters of Bhimbetka — 1. Madhya Pradesh 2. Assam 3. Gujarat 4. Karnataka","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Hampi – Karnataka; Champaner-Pavagadh – Gujarat; Manas – Assam; Bhimbetka – Madhya Pradesh.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"विश्व धरोहर स्थल का उसके राज्य से मिलान कीजिए: A. हम्पी के स्मारक समूह B. चंपानेर-पावागढ़ C. मानस वन्यजीव अभयारण्य D. भीमबेटका के शैलाश्रय — 1. मध्य प्रदेश 2. असम 3. गुजरात 4. कर्नाटक","optionsHi":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"हम्पी – कर्नाटक; चंपानेर-पावागढ़ – गुजरात; मानस – असम; भीमबेटका – मध्य प्रदेश।"},
  {"id":"history-art-culture-79","question":"How many of these are on UNESCO's list of the Intangible Cultural Heritage of Humanity? Tradition of Vedic chanting, Navroz, Chhau dance, Kathakali","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Vedic chanting (2008), Navroz (2016, a multinational listing including India) and Chhau (2010) are listed. Kathakali is not; Kerala's listed forms are Kutiyattam and Mudiyettu.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने यूनेस्को की मानवता की अमूर्त सांस्कृतिक विरासत की सूची में हैं? वैदिक मंत्रोच्चार की परंपरा, नवरोज़, छऊ नृत्य, कथकली","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"वैदिक मंत्रोच्चार (2008), नवरोज़ (2016, भारत सहित बहुराष्ट्रीय सूचीकरण) और छऊ (2010) सूचीबद्ध हैं। कथकली सूचीबद्ध नहीं है; केरल के सूचीबद्ध रूप कुटियाट्टम और मुदियेट्टु हैं।"},
  {"id":"history-art-culture-80","question":"Assertion (A): The Sun Temple at Konark is also called the Black Pagoda. Reason (R): It is built in the Dravida style.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A is true: European sailors called it the Black Pagoda. R is false: Konark is in the Kalinga variety of the Nagara style.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): कोणार्क के सूर्य मंदिर को 'ब्लैक पगोडा' भी कहा जाता है। कारण (R): यह द्रविड़ शैली में बना है।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है, लेकिन R गलत है","A गलत है, लेकिन R सही है"],"explanationHi":"A सही है: यूरोपीय नाविक इसे ब्लैक पगोडा कहते थे। R गलत है: कोणार्क नागर शैली की कलिंग शैली में बना है।"},
  {"id":"history-art-culture-81","question":"Which one of the following is NOT among the classical dance forms recognised by the Sangeet Natak Akademi?","options":["Kathak","Sattriya","Yakshagana","Mohiniyattam"],"answer":2,"explanation":"Yakshagana is a traditional theatre form of Karnataka. The eight recognised forms are Bharatanatyam, Kathak, Kathakali, Kuchipudi, Manipuri, Mohiniyattam, Odissi and Sattriya.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"निम्नलिखित में से कौन संगीत नाटक अकादमी द्वारा मान्यता प्राप्त शास्त्रीय नृत्य रूपों में शामिल नहीं है?","optionsHi":["कथक","सत्रीया","यक्षगान","मोहिनीअट्टम"],"explanationHi":"यक्षगान कर्नाटक की एक पारंपरिक रंगमंच शैली है। मान्यता प्राप्त आठ रूप भरतनाट्यम, कथक, कथकली, कुचिपुड़ी, मणिपुरी, मोहिनीअट्टम, ओडिसी और सत्रीया हैं।"},
  {"id":"history-art-culture-82","question":"Match the Mughal monument with its location: A. Bibi ka Maqbara B. Shalimar Bagh (Jahangir) C. Jama Masjid (Shah Jahan) D. Tomb of Akbar — 1. Sikandra 2. Delhi 3. Srinagar 4. Aurangabad","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Bibi ka Maqbara (Aurangzeb's son, for his mother) – Aurangabad; Jahangir's Shalimar Bagh – Srinagar; Shah Jahan's Jama Masjid – Delhi; Akbar's tomb – Sikandra near Agra.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मुगल स्मारक का उसके स्थान से मिलान कीजिए: A. बीबी का मकबरा B. शालीमार बाग (जहाँगीर) C. जामा मस्जिद (शाहजहाँ) D. अकबर का मकबरा — 1. सिकंदरा 2. दिल्ली 3. श्रीनगर 4. औरंगाबाद","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"explanationHi":"बीबी का मकबरा (औरंगजेब के पुत्र द्वारा अपनी माता के लिए) – औरंगाबाद; जहाँगीर का शालीमार बाग – श्रीनगर; शाहजहाँ की जामा मस्जिद – दिल्ली; अकबर का मकबरा – आगरा के पास सिकंदरा।"},
  {"id":"history-art-culture-83","question":"How many of these statements about Kathak are correct? I. Its main gharanas are Lucknow, Jaipur and Banaras. II. Fast spins (chakkars) are a feature of the dance. III. It developed mainly in the temples of Odisha. IV. Birju Maharaj belonged to the Jaipur gharana.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. Kathak grew from north Indian kathakars and the Mughal and Awadh courts (Odissi is the Odisha form), and Birju Maharaj was of the Lucknow gharana.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कथक के बारे में इनमें से कितने कथन सही हैं? I. इसके मुख्य घराने लखनऊ, जयपुर और बनारस हैं। II. तेज चक्कर इस नृत्य की विशेषता हैं। III. इसका विकास मुख्यतः ओडिशा के मंदिरों में हुआ। IV. बिरजू महाराज जयपुर घराने के थे।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। कथक उत्तर भारत के कथाकारों तथा मुगल और अवध के दरबारों से विकसित हुआ (ओडिसी ओडिशा का रूप है), और बिरजू महाराज लखनऊ घराने के थे।"},
  {"id":"history-art-culture-84","question":"Arrange these treatises on music in chronological order: 1. Natyashastra 2. Sangita Ratnakara 3. Brihaddeshi 4. Sangita Parijata","options":["1-2-3-4","1-3-2-4","3-1-2-4","1-3-4-2"],"answer":1,"explanation":"Bharata's Natyashastra (c. 2nd century BCE–2nd century CE); Matanga's Brihaddeshi (c. 9th century); Sarangadeva's Sangita Ratnakara (13th century); Ahobala's Sangita Parijata (17th century).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संगीत संबंधी इन ग्रंथों को कालक्रम के अनुसार व्यवस्थित कीजिए: 1. नाट्यशास्त्र 2. संगीत रत्नाकर 3. बृहद्देशी 4. संगीत पारिजात","optionsHi":["1-2-3-4","1-3-2-4","3-1-2-4","1-3-4-2"],"explanationHi":"भरत का नाट्यशास्त्र (लगभग दूसरी शताब्दी ई.पू.-दूसरी शताब्दी ई.); मतंग की बृहद्देशी (लगभग 9वीं शताब्दी); शार्ङ्गदेव का संगीत रत्नाकर (13वीं शताब्दी); अहोबल का संगीत पारिजात (17वीं शताब्दी)।"},
  {"id":"history-art-culture-85","question":"Which pair of textile and state is NOT correctly matched?","options":["Pashmina — Jammu and Kashmir","Pochampally ikat — Telangana","Chanderi — Madhya Pradesh","Kanjeevaram silk — Kerala"],"answer":3,"explanation":"Kanjeevaram (Kanchipuram) silk is from Tamil Nadu. The other pairs are correct, and all four are GI-tagged.","difficulty":"very-hard","source":"SSC CGL · State PSCs","questionHi":"वस्त्र और राज्य का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["पश्मीना — जम्मू और कश्मीर","पोचमपल्ली इकत — तेलंगाना","चंदेरी — मध्य प्रदेश","कांजीवरम रेशम — केरल"],"explanationHi":"कांजीवरम (कांचीपुरम) रेशम तमिलनाडु का है। अन्य युग्म सही हैं, और चारों को GI टैग प्राप्त है।"},
  {"id":"history-art-culture-86","question":"Kalaripayattu, one of the oldest martial arts of India, belongs to:","options":["Kerala","Punjab","Manipur","Tamil Nadu"],"answer":0,"explanation":"Kalaripayattu is from Kerala. Gatka is Punjabi, Thang-ta Manipuri and Silambam Tamil.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"भारत की सबसे प्राचीन मार्शल आर्ट्स में से एक कलरिपयट्टु किस राज्य से संबंधित है?","optionsHi":["केरल","पंजाब","मणिपुर","तमिलनाडु"],"explanationHi":"कलरिपयट्टु केरल की है। गतका पंजाब की, थांग-ता मणिपुर की और सिलंबम तमिलनाडु की है।"},
  {"id":"history-art-culture-87","question":"The Hemis festival, with masked cham dances honouring Guru Padmasambhava, is celebrated in:","options":["Sikkim","Arunachal Pradesh","Ladakh","Himachal Pradesh"],"answer":2,"explanation":"The festival is held at Hemis monastery near Leh, Ladakh. Losoong is a Sikkimese festival.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"गुरु पद्मसंभव के सम्मान में मुखौटा 'छम' नृत्यों वाला हेमिस उत्सव कहाँ मनाया जाता है?","optionsHi":["सिक्किम","अरुणाचल प्रदेश","लद्दाख","हिमाचल प्रदेश"],"explanationHi":"यह उत्सव लद्दाख में लेह के पास हेमिस मठ में होता है। लोसूंग सिक्किम का त्योहार है।"},
  {"id":"history-art-culture-88","question":"Bathukamma, a floral festival celebrated by women, is a state festival of:","options":["Karnataka","Odisha","Kerala","Telangana"],"answer":3,"explanation":"Bathukamma, in which women arrange flowers in conical stacks and sing around them, is Telangana's state festival.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"महिलाओं द्वारा मनाया जाने वाला पुष्प उत्सव बथुकम्मा किस राज्य का राजकीय त्योहार है?","optionsHi":["कर्नाटक","ओडिशा","केरल","तेलंगाना"],"explanationHi":"बथुकम्मा, जिसमें महिलाएँ फूलों को शंकु के आकार में सजाती हैं और उनके चारों ओर गीत गाती हैं, तेलंगाना का राजकीय त्योहार है।"},
  {"id":"history-art-culture-89","question":"Kerala Kalamandalam, which revived Kathakali and other Kerala art forms, was founded in 1930 by the poet:","options":["Kumaran Asan","Vallathol Narayana Menon","Ulloor S. Parameswara Iyer","Kunchan Nambiar"],"answer":1,"explanation":"Vallathol set up Kalamandalam, now a deemed university at Cheruthuruthy. Kunchan Nambiar was an 18th-century poet who created Ottan Thullal.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"केरल कलामंडलम, जिसने कथकली और केरल की अन्य कला रूपों को पुनर्जीवित किया, की स्थापना 1930 में किस कवि ने की थी?","optionsHi":["कुमारन आशान","वल्लथोल नारायण मेनन","उल्लूर एस. परमेश्वर अय्यर","कुंचन नंबियार"],"explanationHi":"वल्लथोल ने कलामंडलम की स्थापना की, जो अब चेरुतुरुत्ति में एक मानित विश्वविद्यालय है। कुंचन नंबियार 18वीं शताब्दी के कवि थे जिन्होंने ओट्टन तुल्लल की रचना की।"},
  {"id":"history-art-culture-90","question":"In Kuchipudi, the item called Tarangam is notable because the dancer:","options":["Wears a mask throughout","Dances on the rim of a brass plate","Performs in total silence","Sings and plays the mridangam at once"],"answer":1,"explanation":"In Tarangam the dancer balances on the edges of a brass plate, sometimes with a pot of water on the head, a signature Kuchipudi feat.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"कुचिपुड़ी में 'तरंगम' प्रस्तुति इसलिए उल्लेखनीय है क्योंकि नर्तक/नर्तकी:","optionsHi":["पूरे समय मुखौटा पहनता है","पीतल की थाली के किनारों पर नृत्य करता है","पूर्ण मौन में प्रस्तुति देता है","एक साथ गाता और मृदंग बजाता है"],"explanationHi":"तरंगम में नर्तक पीतल की थाली के किनारों पर संतुलन बनाता है, कभी-कभी सिर पर पानी का घड़ा भी रखकर; यह कुचिपुड़ी की पहचान वाला करतब है।"},
  {"id":"history-art-culture-91","question":"The Sangai Festival, named after the brow-antlered deer, is held every November in:","options":["Manipur","Mizoram","Tripura","Meghalaya"],"answer":0,"explanation":"Manipur's tourism festival is named after the Sangai, the State animal found in Keibul Lamjao National Park.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"भौंहदार सींगों वाले हिरण के नाम पर रखा गया संगाई महोत्सव प्रत्येक नवंबर में कहाँ आयोजित होता है?","optionsHi":["मणिपुर","मिज़ोरम","त्रिपुरा","मेघालय"],"explanationHi":"मणिपुर का पर्यटन उत्सव संगाई के नाम पर है, जो राज्य पशु है और केइबुल लामजाओ राष्ट्रीय उद्यान में पाया जाता है।"},
  {"id":"history-art-culture-92","question":"The Sun Temple at Modhera, built under the Solanki (Chaulukya) ruler Bhima I, is in:","options":["Rajasthan","Odisha","Gujarat","Madhya Pradesh"],"answer":2,"explanation":"Modhera, in Mehsana district of Gujarat, has a stepped tank (Surya Kund) in front of the temple. The Konark Sun Temple is in Odisha.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"सोलंकी (चौलुक्य) शासक भीम प्रथम के काल में बना मोढेरा का सूर्य मंदिर कहाँ स्थित है?","optionsHi":["राजस्थान","ओडिशा","गुजरात","मध्य प्रदेश"],"explanationHi":"गुजरात के मेहसाणा जिले में स्थित मोढेरा में मंदिर के सामने एक सीढ़ीदार कुंड (सूर्य कुंड) है। कोणार्क का सूर्य मंदिर ओडिशा में है।"},
  {"id":"history-art-culture-93","question":"Ottan Thullal, a satirical solo performance art of Kerala, was created by:","options":["Kunchan Nambiar","Vallathol Narayana Menon","Swathi Thirunal","Thunchath Ezhuthachan"],"answer":0,"explanation":"Kunchan Nambiar created Ottan Thullal in the 18th century, using simple Malayalam and humour. Swathi Thirunal was a composer-king of Travancore.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"केरल की व्यंग्यात्मक एकल प्रदर्शन कला ओट्टन तुल्लल की रचना किसने की?","optionsHi":["कुंचन नंबियार","वल्लथोल नारायण मेनन","स्वाति तिरुनाल","तुंचत एषुत्तच्छन"],"explanationHi":"कुंचन नंबियार ने 18वीं शताब्दी में सरल मलयालम और हास्य के प्रयोग से ओट्टन तुल्लल की रचना की। स्वाति तिरुनाल त्रावणकोर के संगीतकार-राजा थे।"},
  {"id":"history-art-culture-94","question":"The famous stone chariot (ratha) shrine of Garuda stands in the courtyard of which temple at Hampi?","options":["Virupaksha temple","Hazara Rama temple","Achyutaraya temple","Vitthala temple"],"answer":3,"explanation":"The stone chariot is in the Vitthala temple complex, also known for its musical pillars. The Virupaksha temple is Hampi's main living temple.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"गरुड़ का प्रसिद्ध पत्थर का रथ मंदिर हम्पी के किस मंदिर के प्रांगण में स्थित है?","optionsHi":["विरूपाक्ष मंदिर","हज़ार राम मंदिर","अच्युतराय मंदिर","विट्ठल मंदिर"],"explanationHi":"पत्थर का रथ विट्ठल मंदिर परिसर में है, जो अपने संगीतमय स्तंभों के लिए भी जाना जाता है। विरूपाक्ष मंदिर हम्पी का मुख्य जीवंत मंदिर है।"},
  {"id":"history-art-culture-95","question":"The monolithic Pancha Rathas at Mamallapuram were carved under the Pallava king:","options":["Mahendravarman I","Narasimhavarman I","Narasimhavarman II","Nandivarman II"],"answer":1,"explanation":"Narasimhavarman I “Mamalla” (7th century) is credited with the rathas, and the town is named after him. The structural Shore Temple came under Narasimhavarman II.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"महाबलीपुरम के एकाश्म पंच रथ किस पल्लव राजा के काल में तराशे गए?","optionsHi":["महेंद्रवर्मन प्रथम","नरसिंहवर्मन प्रथम","नरसिंहवर्मन द्वितीय","नंदिवर्मन द्वितीय"],"explanationHi":"रथों का श्रेय नरसिंहवर्मन प्रथम 'ममल्ल' (7वीं शताब्दी) को दिया जाता है, और नगर का नाम उन्हीं के नाम पर पड़ा। संरचनात्मक तट मंदिर नरसिंहवर्मन द्वितीय के काल में बना।"},
  {"id":"history-art-culture-96","question":"The Virupaksha temple at Pattadakal was built to commemorate a victory over the Pallavas by:","options":["Pulakeshin II","Queen Trailokyamahadevi","Queen Lokamahadevi","Krishna I"],"answer":2,"explanation":"Lokamahadevi had the temple built after her husband Vikramaditya II's victory at Kanchipuram (8th century); it shows the influence of the Kailasanatha temple there. Her sister Trailokyamahadevi built the adjoining Mallikarjuna temple.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पट्टदकल का विरूपाक्ष मंदिर पल्लवों पर विजय की स्मृति में किसने बनवाया?","optionsHi":["पुलकेशिन द्वितीय","रानी त्रैलोक्यमहादेवी","रानी लोकमहादेवी","कृष्ण प्रथम"],"explanationHi":"लोकमहादेवी ने अपने पति विक्रमादित्य द्वितीय की कांचीपुरम में विजय (8वीं शताब्दी) के बाद यह मंदिर बनवाया; इस पर वहाँ के कैलासनाथ मंदिर का प्रभाव दिखता है। उनकी बहन त्रैलोक्यमहादेवी ने निकटवर्ती मल्लिकार्जुन मंदिर बनवाया।"},
  {"id":"history-art-culture-97","question":"The present Jagannath temple at Puri was begun by the Eastern Ganga ruler:","options":["Narasimhadeva I","Kapilendra Deva Gajapati","Anantavarman Chodaganga","Prataparudra Deva"],"answer":2,"explanation":"Anantavarman Chodaganga (12th century) began it. Narasimhadeva I, a later Eastern Ganga king, built the Konark Sun Temple in the 13th century.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"पुरी के वर्तमान जगन्नाथ मंदिर का निर्माण किस पूर्वी गंग शासक ने आरंभ किया?","optionsHi":["नरसिंहदेव प्रथम","कपिलेंद्र देव गजपति","अनंतवर्मन चोडगंग","प्रतापरुद्र देव"],"explanationHi":"अनंतवर्मन चोडगंग (12वीं शताब्दी) ने इसे आरंभ किया। परवर्ती पूर्वी गंग राजा नरसिंहदेव प्रथम ने 13वीं शताब्दी में कोणार्क का सूर्य मंदिर बनवाया।"},
  {"id":"history-art-culture-98","question":"Which is regarded as the largest and best-preserved rock-cut chaitya hall in India?","options":["Karla (Karle)","Bhaja","Kanheri","Ajanta Cave 26"],"answer":0,"explanation":"The Karla chaitya near Lonavala, of the 1st century CE, has a high vaulted roof and a wooden umbrella over the stupa. Bhaja is an earlier, smaller chaitya.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत का सबसे बड़ा और सबसे अच्छी तरह संरक्षित चट्टान काटकर बना चैत्य-गृह कौन-सा माना जाता है?","optionsHi":["कार्ला (कार्ले)","भाजा","कन्हेरी","अजंता गुफा 26"],"explanationHi":"लोनावला के पास पहली शताब्दी ई. का कार्ला चैत्य ऊँची मेहराबदार छत और स्तूप के ऊपर लकड़ी के छत्र वाला है। भाजा एक पुराना, छोटा चैत्य है।"},
  {"id":"history-art-culture-99","question":"The scheme of 72 melakarta (parent) ragas of Carnatic music was set out in the 17th century by:","options":["Purandaradasa","Tyagaraja","Sarngadeva","Venkatamakhin"],"answer":3,"explanation":"Venkatamakhin's Chaturdandi Prakashika laid down the 72-melakarta system. Sarngadeva wrote the 13th-century Sangita Ratnakara.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कर्नाटक संगीत के 72 मेलकर्ता (जनक) रागों की योजना 17वीं शताब्दी में किसने प्रस्तुत की?","optionsHi":["पुरंदरदास","त्यागराज","शार्ङ्गदेव","वेंकटमखिन"],"explanationHi":"वेंकटमखिन की चतुर्दंडी प्रकाशिका ने 72 मेलकर्ता पद्धति निर्धारित की। शार्ङ्गदेव ने 13वीं शताब्दी का संगीत रत्नाकर लिखा।"},
  {"id":"history-art-culture-100","question":"Tappa, a light classical vocal form with quick, knotted phrases, was developed from the songs of Punjabi camel drivers by:","options":["Shori Miyan","Sadarang","Tansen","Baiju Bawra"],"answer":0,"explanation":"Ghulam Nabi “Shori Miyan” refined tappa in the 18th century. Sadarang is linked to the development of khayal at Muhammad Shah's court.","difficulty":"hard","source":"UPSC Prelims","questionHi":"तेज़, गुँथे हुए स्वर-समूहों वाला सुगम-शास्त्रीय गायन रूप टप्पा, पंजाबी ऊँट चालकों के गीतों से किसने विकसित किया?","optionsHi":["शोरी मियाँ","सदारंग","तानसेन","बैजू बावरा"],"explanationHi":"गुलाम नबी 'शोरी मियाँ' ने 18वीं शताब्दी में टप्पा को परिष्कृत किया। सदारंग का संबंध मुहम्मद शाह के दरबार में ख़याल के विकास से है।"},
  {"id":"history-art-culture-101","question":"Thumri, the semi-classical form centred on romantic and devotional themes, flourished especially at the court of:","options":["Sawai Jai Singh at Jaipur","Wajid Ali Shah at Lucknow","Tipu Sultan at Srirangapatna","Ranjit Singh at Lahore"],"answer":1,"explanation":"The last Nawab of Awadh, Wajid Ali Shah, patronised thumri and Kathak in 19th-century Lucknow.","difficulty":"hard","source":"UPSC Prelims","questionHi":"प्रेम और भक्ति विषयों पर केंद्रित अर्ध-शास्त्रीय रूप ठुमरी विशेष रूप से किसके दरबार में फली-फूली?","optionsHi":["जयपुर में सवाई जय सिंह","लखनऊ में वाजिद अली शाह","श्रीरंगपट्टनम में टीपू सुल्तान","लाहौर में रणजीत सिंह"],"explanationHi":"अवध के अंतिम नवाब वाजिद अली शाह ने 19वीं शताब्दी के लखनऊ में ठुमरी और कथक को संरक्षण दिया।"},
  {"id":"history-art-culture-102","question":"Ramman, a religious festival and ritual theatre inscribed by UNESCO in 2009, belongs to:","options":["Himachal Pradesh","Uttarakhand","Sikkim","Jammu and Kashmir"],"answer":1,"explanation":"Ramman is performed in the Garhwal villages of Saloor-Dungra in Uttarakhand, in honour of the local deity Bhumiyal Devta.","difficulty":"hard","source":"UPSC Prelims","questionHi":"2009 में यूनेस्को द्वारा सूचीबद्ध धार्मिक उत्सव और अनुष्ठानिक रंगमंच रम्मन किस राज्य का है?","optionsHi":["हिमाचल प्रदेश","उत्तराखंड","सिक्किम","जम्मू और कश्मीर"],"explanationHi":"रम्मन उत्तराखंड के गढ़वाल के सलूड़-डुंगरा गाँवों में स्थानीय देवता भूमियाल देवता के सम्मान में किया जाता है।"},
  {"id":"history-art-culture-103","question":"Pithora painting, done on house walls to invoke the deity Baba Pithora, is a ritual art of the:","options":["Gonds of Madhya Pradesh","Warlis of the Thane–Palghar belt","Santhals of Jharkhand","Rathwas and Bhils of Gujarat"],"answer":3,"explanation":"Pithora paintings come mainly from the Rathwas and Bhils of central Gujarat and adjoining Madhya Pradesh. Warli art uses white stick figures; Gond art uses dots and lines.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बाबा पिथोरा देवता का आह्वान करने के लिए घरों की दीवारों पर बनाई जाने वाली पिथोरा चित्रकला किनकी अनुष्ठानिक कला है?","optionsHi":["मध्य प्रदेश के गोंड","ठाणे-पालघर क्षेत्र के वारली","झारखंड के संथाल","गुजरात के राठवा और भील"],"explanationHi":"पिथोरा चित्र मुख्यतः मध्य गुजरात और निकटवर्ती मध्य प्रदेश के राठवा और भील समुदायों के हैं। वारली कला में सफेद आकृतियाँ और गोंड कला में बिंदु और रेखाएँ होती हैं।"},
  {"id":"history-art-culture-104","question":"The Airavatesvara temple at Darasuram, one of the Great Living Chola Temples, was built by:","options":["Rajaraja I","Rajendra I","Kulottunga I","Rajaraja II"],"answer":3,"explanation":"Rajaraja II built Darasuram in the 12th century. Rajaraja I built the Brihadeeswara at Thanjavur and Rajendra I the temple at Gangaikondacholapuram.","difficulty":"hard","source":"UPSC Prelims","questionHi":"महान जीवंत चोल मंदिरों में शामिल दारासुरम का ऐरावतेश्वर मंदिर किसने बनवाया?","optionsHi":["राजराज प्रथम","राजेंद्र प्रथम","कुलोत्तुंग प्रथम","राजराज द्वितीय"],"explanationHi":"राजराज द्वितीय ने 12वीं शताब्दी में दारासुरम बनवाया। राजराज प्रथम ने तंजावुर का बृहदीश्वर और राजेंद्र प्रथम ने गंगैकोंडचोलपुरम का मंदिर बनवाया।"},
  {"id":"history-art-culture-105","question":"Match the exponent with the dance form: A. Kelucharan Mohapatra B. Guru Bipin Singh C. Kalamandalam Kalyanikutty Amma D. Birju Maharaj — 1. Kathak 2. Mohiniyattam 3. Manipuri 4. Odissi","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Kelucharan Mohapatra revived Odissi, Guru Bipin Singh shaped modern Manipuri, Kalyanikutty Amma revived Mohiniyattam and Birju Maharaj led the Lucknow gharana of Kathak.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"कलाकार का नृत्य रूप से मिलान कीजिए: A. केलुचरण महापात्र B. गुरु बिपिन सिंह C. कलामंडलम कल्याणिकुट्टी अम्मा D. बिरजू महाराज — 1. कथक 2. मोहिनीअट्टम 3. मणिपुरी 4. ओडिसी","optionsHi":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"केलुचरण महापात्र ने ओडिसी को पुनर्जीवित किया, गुरु बिपिन सिंह ने आधुनिक मणिपुरी को आकार दिया, कल्याणिकुट्टी अम्मा ने मोहिनीअट्टम को पुनर्जीवित किया और बिरजू महाराज कथक के लखनऊ घराने के प्रमुख थे।"},
  {"id":"history-art-culture-106","question":"Match the painting tradition with its state: A. Cheriyal scrolls B. Saura (Idital) C. Sohrai D. Kalighat — 1. West Bengal 2. Jharkhand 3. Odisha 4. Telangana","options":["A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Cheriyal narrative scrolls come from Telangana, Saura wall paintings from Odisha, Sohrai mural art from Hazaribagh in Jharkhand and Kalighat pat paintings from Kolkata.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"चित्रकला परंपरा का उसके राज्य से मिलान कीजिए: A. चेरियाल पटचित्र B. सौरा (इदिताल) C. सोहराई D. कालीघाट — 1. पश्चिम बंगाल 2. झारखंड 3. ओडिशा 4. तेलंगाना","optionsHi":["A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1"],"explanationHi":"चेरियाल कथात्मक पटचित्र तेलंगाना के हैं, सौरा भित्ति चित्र ओडिशा के, सोहराई भित्ति कला झारखंड के हज़ारीबाग की और कालीघाट पट चित्र कोलकाता के हैं।"},
  {"id":"history-art-culture-107","question":"In the Kalinga (Odisha) style of temple architecture, the “jagamohana” is the:","options":["Inner sanctum housing the deity","Assembly hall before the sanctum","Hall of offerings at the far end","Crowning ribbed stone disc"],"answer":1,"explanation":"An Odisha temple typically has the deul (sanctum with tower), jagamohana (assembly hall), nata mandira (dance hall) and bhoga mandapa (offering hall). The ribbed disc is the amalaka.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मंदिर स्थापत्य की कलिंग (ओडिशा) शैली में 'जगमोहन' क्या है?","optionsHi":["देवता को धारण करने वाला भीतरी गर्भगृह","गर्भगृह के सामने का सभा-मंडप","दूर छोर पर स्थित भोग-मंडप","शीर्ष पर धारीदार पत्थर की चकती"],"explanationHi":"ओडिशा के मंदिर में सामान्यतः देउल (शिखर सहित गर्भगृह), जगमोहन (सभा-मंडप), नट मंदिर (नृत्य-मंडप) और भोग मंडप होते हैं। धारीदार चकती आमलक है।"},
  {"id":"history-art-culture-108","question":"Match the part of a stupa with its description: A. Anda B. Harmika C. Medhi D. Torana — 1. Ornamental gateway 2. Hemispherical dome 3. Raised terrace or base used for circumambulation 4. Railed square platform on top of the dome","options":["A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1","A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3"],"answer":0,"explanation":"The anda is the dome, the harmika the railed balcony from which the chhatra rises, the medhi the raised terrace, and the toranas the carved gateways, as at Sanchi.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"स्तूप के भाग का उसके विवरण से मिलान कीजिए: A. अंड B. हर्मिका C. मेधि D. तोरण — 1. अलंकृत प्रवेश-द्वार 2. अर्धगोलाकार गुंबद 3. प्रदक्षिणा के लिए प्रयुक्त ऊँचा चबूतरा या आधार 4. गुंबद के शीर्ष पर घिरा हुआ वर्गाकार मंच","optionsHi":["A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1","A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3"],"explanationHi":"अंड गुंबद है, हर्मिका वह घिरी हुई वेदिका है जिससे छत्र उठता है, मेधि ऊँचा चबूतरा है, और तोरण नक्काशीदार प्रवेश-द्वार हैं, जैसे साँची में।"},
  {"id":"history-art-culture-109","question":"Match the folk theatre with its state: A. Jatra B. Tamasha C. Bhavai D. Nautanki — 1. Uttar Pradesh 2. Gujarat 3. Maharashtra 4. West Bengal","options":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"answer":1,"explanation":"Jatra is Bengali open-air theatre, Tamasha is Marathi, Bhavai is from Gujarat and Nautanki from Uttar Pradesh.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"लोक रंगमंच का उसके राज्य से मिलान कीजिए: A. जात्रा B. तमाशा C. भवाई D. नौटंकी — 1. उत्तर प्रदेश 2. गुजरात 3. महाराष्ट्र 4. पश्चिम बंगाल","optionsHi":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"जात्रा बंगाल का खुला रंगमंच है, तमाशा मराठी है, भवाई गुजरात की और नौटंकी उत्तर प्रदेश की है।"},
  {"id":"history-art-culture-110","question":"Consider the following statements: 1. Pattadakal has temples in both the Nagara and the Dravida styles. 2. Pattadakal is a UNESCO World Heritage Site. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. The Chalukyan temples at Pattadakal, such as the Papanatha (Nagara) and Virupaksha (Dravida), were inscribed in 1987.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. पट्टदकल में नागर और द्रविड़ दोनों शैलियों के मंदिर हैं। 2. पट्टदकल यूनेस्को का विश्व धरोहर स्थल है। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। पट्टदकल के चालुक्य मंदिर, जैसे पापनाथ (नागर) और विरूपाक्ष (द्रविड़), 1987 में सूची में शामिल हुए।"},
  {"id":"history-art-culture-111","question":"How many of these temples are part of the UNESCO site “Great Living Chola Temples”? Brihadeeswara at Thanjavur, Brihadeeswara at Gangaikondacholapuram, Airavatesvara at Darasuram, Meenakshi at Madurai","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"The first three are Chola temples inscribed under this site. The Meenakshi temple at Madurai is largely of the Nayaka period and is not part of it.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने मंदिर यूनेस्को स्थल 'महान जीवंत चोल मंदिर' का भाग हैं? तंजावुर का बृहदीश्वर, गंगैकोंडचोलपुरम का बृहदीश्वर, दारासुरम का ऐरावतेश्वर, मदुरै का मीनाक्षी","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"पहले तीन चोल मंदिर इस स्थल के अंतर्गत सूचीबद्ध हैं। मदुरै का मीनाक्षी मंदिर मुख्यतः नायक काल का है और इसका भाग नहीं है।"},
  {"id":"history-art-culture-112","question":"Arrange these Indian elements in the order in which they were added to UNESCO's Intangible Cultural Heritage list: 1. Kutiyattam 2. Ramman 3. Sankirtana of Manipur 4. Garba of Gujarat","options":["1, 2, 3, 4","2, 1, 3, 4","1, 3, 2, 4","1, 2, 4, 3"],"answer":0,"explanation":"Kutiyattam was among the first (proclaimed in 2001), Ramman was inscribed in 2009, Sankirtana in 2013 and Garba in 2023.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"यूनेस्को की अमूर्त सांस्कृतिक विरासत सूची में इन भारतीय तत्वों को जोड़े जाने के क्रम में व्यवस्थित कीजिए: 1. कुटियाट्टम 2. रम्मन 3. मणिपुर का संकीर्तन 4. गुजरात का गरबा","optionsHi":["1, 2, 3, 4","2, 1, 3, 4","1, 3, 2, 4","1, 2, 4, 3"],"explanationHi":"कुटियाट्टम पहली घोषणाओं (2001) में था, रम्मन 2009 में, संकीर्तन 2013 में और गरबा 2023 में सूची में शामिल हुआ।"},
  {"id":"history-art-culture-113","question":"Match the martial art with its state: A. Gatka B. Thang-ta C. Silambam D. Mardani Khel — 1. Maharashtra 2. Tamil Nadu 3. Manipur 4. Punjab","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1"],"answer":2,"explanation":"Gatka is the Sikh art of stick and sword, Thang-ta the Manipuri art of sword and spear, Silambam a Tamil staff art and Mardani Khel a Maratha weapon art.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"मार्शल आर्ट का उसके राज्य से मिलान कीजिए: A. गतका B. थांग-ता C. सिलंबम D. मर्दानी खेल — 1. महाराष्ट्र 2. तमिलनाडु 3. मणिपुर 4. पंजाब","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1"],"explanationHi":"गतका लाठी और तलवार की सिख कला है, थांग-ता तलवार और भाले की मणिपुरी कला, सिलंबम तमिल लाठी कला और मर्दानी खेल मराठा शस्त्र कला है।"},
  {"id":"history-art-culture-114","question":"Assertion (A): The Dilwara and Ranakpur temples are celebrated for their intricate marble carving. Reason (R): Both temple complexes are in Rajasthan.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both are true, but location does not explain the carving. The fine work reflects rich Jain patrons such as Vimal Shah and Dharna Shah and skilled sompura craftsmen.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): दिलवाड़ा और रणकपुर के मंदिर अपनी जटिल संगमरमर की नक्काशी के लिए प्रसिद्ध हैं। कारण (R): दोनों मंदिर परिसर राजस्थान में हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं पर R, A की सही व्याख्या नहीं है","A सही है पर R गलत है","A गलत है पर R सही है"],"explanationHi":"दोनों सही हैं, पर स्थान नक्काशी की व्याख्या नहीं करता। बारीक कार्य विमल शाह और धरणा शाह जैसे धनी जैन संरक्षकों और कुशल सोमपुरा कारीगरों को दर्शाता है।"},
  {"id":"history-art-culture-115","question":"Match the building with its architect: A. Victoria Memorial, Kolkata B. Rashtrapati Bhavan, New Delhi C. Gateway of India, Mumbai D. Capitol Complex, Chandigarh — 1. William Emerson 2. George Wittet 3. Le Corbusier 4. Edwin Lutyens","options":["A-1, B-4, C-3, D-2","A-4, B-1, C-2, D-3","A-1, B-4, C-2, D-3","A-2, B-4, C-1, D-3"],"answer":2,"explanation":"Emerson designed the Victoria Memorial, Lutyens the Viceroy's House (now Rashtrapati Bhavan), Wittet the Gateway of India, and Le Corbusier the Capitol Complex, a World Heritage Site since 2016.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"इमारत का उसके वास्तुकार से मिलान कीजिए: A. विक्टोरिया मेमोरियल, कोलकाता B. राष्ट्रपति भवन, नई दिल्ली C. गेटवे ऑफ इंडिया, मुंबई D. कैपिटल कॉम्प्लेक्स, चंडीगढ़ — 1. विलियम एमर्सन 2. जॉर्ज विटेट 3. ले कॉर्बूज़िए 4. एडविन लुटियंस","optionsHi":["A-1, B-4, C-3, D-2","A-4, B-1, C-2, D-3","A-1, B-4, C-2, D-3","A-2, B-4, C-1, D-3"],"explanationHi":"एमर्सन ने विक्टोरिया मेमोरियल, लुटियंस ने वायसराय हाउस (अब राष्ट्रपति भवन), विटेट ने गेटवे ऑफ इंडिया और ले कॉर्बूज़िए ने कैपिटल कॉम्प्लेक्स की रूपरेखा बनाई, जो 2016 से विश्व धरोहर स्थल है।"},
  {"id":"history-art-culture-116","question":"How many of these statements about traditional theatre in India are correct? I. Yakshagana is a dance-drama of coastal Karnataka. II. Ankiya Naat, one-act devotional plays, were created by Sankaradeva in Assam. III. Therukoothu is a street-theatre tradition of Kerala. IV. Bhaona is the traditional folk theatre of Gujarat.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. Therukoothu is the street theatre of Tamil Nadu, not Kerala, and Bhaona is the staging of Ankiya Naat in Assam; Gujarat's folk theatre is Bhavai.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत के पारंपरिक रंगमंच के बारे में इनमें से कितने कथन सही हैं? I. यक्षगान तटीय कर्नाटक की नृत्य-नाटिका है। II. अंकिया नाट, एकांकी भक्ति नाटक, असम में शंकरदेव ने रचे। III. थेरुकूथु केरल की नुक्कड़ नाट्य परंपरा है। IV. भाओना गुजरात का पारंपरिक लोक रंगमंच है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। थेरुकूथु तमिलनाडु का नुक्कड़ रंगमंच है, केरल का नहीं, और भाओना असम में अंकिया नाट का मंचन है; गुजरात का लोक रंगमंच भवाई है।"},
  {"id":"history-art-culture-117","question":"Which Gupta-period temple is regarded as one of the earliest north Indian temples with a shikhara, and an early example of the panchayatana plan?","options":["Temple 17 at Sanchi","Dashavatara temple at Deogarh","Lad Khan temple at Aihole","Kailasanatha temple at Kanchi"],"answer":1,"explanation":"The Dashavatara (Vishnu) temple at Deogarh in Lalitpur district, Uttar Pradesh, of about the 6th century, had a shikhara over the sanctum and four corner shrines. Temple 17 at Sanchi is an earlier flat-roofed shrine; Aihole and Kanchi are later southern monuments.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"गुप्तकालीन कौन-सा मंदिर शिखर वाले सबसे आरंभिक उत्तर भारतीय मंदिरों में और पंचायतन योजना का प्रारंभिक उदाहरण माना जाता है?","optionsHi":["साँची का मंदिर 17","देवगढ़ का दशावतार मंदिर","ऐहोल का लाड़ खान मंदिर","कांची का कैलासनाथ मंदिर"],"explanationHi":"उत्तर प्रदेश के ललितपुर जिले में देवगढ़ का दशावतार (विष्णु) मंदिर, लगभग 6वीं शताब्दी का, गर्भगृह के ऊपर शिखर और चार कोने के मंदिरों वाला था। साँची का मंदिर 17 एक पहले का सपाट छत वाला देवालय है; ऐहोल और कांची के स्मारक बाद के दक्षिणी स्मारक हैं।"},
  {"id":"history-art-culture-118","question":"The four elaborately carved toranas (gateways) of the Great Stupa at Sanchi were added under the:","options":["Mauryas","Shungas","Satavahanas","Kushanas"],"answer":2,"explanation":"The toranas at Sanchi were carved in the first century BCE–CE under Satavahana patronage and show Jataka scenes and events from the Buddha's life. The Shungas added the stone casing and railing, not the gateways.","difficulty":"hard","questionHi":"साँची के महास्तूप के चार अलंकृत तोरण (प्रवेश द्वार) किसके काल में जोड़े गए?","optionsHi":["मौर्यों","शुंगों","सातवाहनों","कुषाणों"],"explanationHi":"साँची के तोरण ईसा पूर्व पहली शताब्दी से ईसा की पहली शताब्दी के बीच सातवाहनों के संरक्षण में उत्कीर्ण हुए और उनमें जातक कथाएँ तथा बुद्ध के जीवन की घटनाएँ दिखती हैं। पत्थर का आवरण और वेदिका शुंगों ने जोड़ी थी, तोरण नहीं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-119","question":"The Hathigumpha inscription at Udayagiri near Bhubaneswar, a long record of the deeds of its king, belongs to:","options":["Kharavela of Kalinga","Ashoka Maurya, the emperor at Pataliputra","Rudradaman, the Shaka satrap of Junagarh","Samudragupta, the Gupta emperor of Pataliputra"],"answer":0,"explanation":"The Hathigumpha inscription, cut in a cave at Udayagiri, narrates year by year the achievements of Kharavela of Kalinga. Rudradaman's record is at Junagadh and Samudragupta's is on the Allahabad pillar.","difficulty":"hard","questionHi":"भुवनेश्वर के निकट उदयगिरि का हाथीगुम्फा अभिलेख, जो अपने राजा के कार्यों का लंबा विवरण है, किससे संबंधित है?","optionsHi":["कलिंग के खारवेल","अशोक मौर्य, पाटलिपुत्र के सम्राट","रुद्रदामन, जूनागढ़ का शक क्षत्रप","समुद्रगुप्त, पाटलिपुत्र का गुप्त सम्राट"],"explanationHi":"उदयगिरि की गुफा में उत्कीर्ण हाथीगुम्फा अभिलेख कलिंग के खारवेल की उपलब्धियों का वर्ष-दर-वर्ष वर्णन करता है। रुद्रदामन का अभिलेख जूनागढ़ में और समुद्रगुप्त का इलाहाबाद स्तंभ पर है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-art-culture-120","question":"Humayun's tomb at Delhi, the first monumental garden-tomb of the Mughals, was commissioned by his widow Haji Begum and designed by the Persian architect:","options":["Ustad Ahmad Lahori","Mirak Mirza Ghiyas","Ustad Isa","Abdul Karim Mamur Khan"],"answer":1,"explanation":"Mirak Mirza Ghiyas, a Persian architect, designed Humayun's tomb in the 1560s, with a charbagh garden and a double dome that foreshadowed the Taj Mahal. Ahmad Lahori is the architect usually credited with the Taj and the Red Fort.","difficulty":"hard","questionHi":"मुगलों का पहला भव्य उद्यान-मकबरा, दिल्ली में हुमायूँ का मकबरा, उनकी विधवा हाजी बेगम ने बनवाया और उसका अभिकल्प किस फारसी वास्तुकार ने बनाया?","optionsHi":["उस्ताद अहमद लाहौरी","मिराक मिर्ज़ा गियास","उस्ताद ईसा","अब्दुल करीम मामूर खान"],"explanationHi":"फारसी वास्तुकार मिराक मिर्ज़ा गियास ने 1560 के दशक में हुमायूँ के मकबरे का अभिकल्प बनाया, जिसमें चारबाग उद्यान और दोहरा गुंबद है जो ताजमहल का पूर्वाभास देता है। अहमद लाहौरी को सामान्यतः ताजमहल और लाल किले का वास्तुकार माना जाता है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-121","question":"The tomb of Itimad-ud-Daulah at Agra, built by Nur Jahan, is notable as the first Mughal building:","options":["Laid out within a charbagh garden","Built of red sandstone with white marble inlay","Topped by a true double dome","Built wholly of marble with extensive pietra dura inlay"],"answer":3,"explanation":"The tomb of Itimad-ud-Daulah, Nur Jahan's father, is regarded as the first Mughal building entirely of marble with extensive pietra dura inlay, a style later perfected in the Taj. The charbagh and double dome had already appeared at Humayun's tomb.","difficulty":"hard","questionHi":"नूरजहाँ द्वारा बनवाया गया आगरा में इतिमादुद्दौला का मकबरा किस दृष्टि से पहली मुगल इमारत के रूप में उल्लेखनीय है?","optionsHi":["चारबाग उद्यान के भीतर बनी","लाल बलुआ पत्थर में सफेद संगमरमर की जड़ाई वाली","सच्चे दोहरे गुंबद से ढकी","पूरी तरह संगमरमर से बनी और व्यापक पिएत्रा ड्यूरा जड़ाई वाली"],"explanationHi":"नूरजहाँ के पिता इतिमादुद्दौला का मकबरा पूरी तरह संगमरमर से बनी और व्यापक पिएत्रा ड्यूरा जड़ाई वाली पहली मुगल इमारत माना जाता है, शैली जो ताज में पराकाष्ठा पर पहुँची। चारबाग और दोहरा गुंबद हुमायूँ के मकबरे में पहले ही आ चुके थे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-122","question":"Akbar's capital at Fatehpur Sikri was abandoned after only about fifteen years chiefly because of:","options":["Floods of the Yamuna that damaged the palaces and the lake embankments","Shortage of water and the court's move to the north-west","An epidemic of plague that killed many courtiers and workmen","Opposition of the orthodox ulama to the new city built by Akbar"],"answer":1,"explanation":"Fatehpur Sikri suffered from an inadequate water supply, and Akbar's campaigns in the Punjab and the north-west took the court to Lahore around 1585. The city was never formally restored as the capital.","difficulty":"moderate","questionHi":"अकबर की राजधानी फतेहपुर सीकरी केवल लगभग पंद्रह वर्ष बाद मुख्यतः किस कारण छोड़ दी गई?","optionsHi":["यमुना की बाढ़ जिसने महलों और झील के बाँधों को क्षति पहुँचाई","पानी की कमी और दरबार का उत्तर-पश्चिम की ओर चला जाना","प्लेग की महामारी जिसने कई दरबारियों और कारीगरों की जान ली","अकबर द्वारा बसाए नए शहर के प्रति रूढ़िवादी उलेमा का विरोध"],"explanationHi":"फतेहपुर सीकरी में पानी की आपूर्ति अपर्याप्त थी और पंजाब तथा उत्तर-पश्चिम में अकबर के अभियानों के कारण दरबार लगभग 1585 में लाहौर चला गया। शहर को फिर औपचारिक रूप से राजधानी नहीं बनाया गया।","source":"SSC CGL · State PCS"},
  {"id":"history-art-culture-123","question":"Ibrahim Rauza at Bijapur, a tomb and mosque on one platform noted for its slender minarets, was built by:","options":["Ibrahim Adil Shah II","Muhammad Adil Shah","Yusuf Adil Shah","Ali Adil Shah I"],"answer":0,"explanation":"Ibrahim Adil Shah II built the Ibrahim Rauza in the early 17th century as a tomb for his queen and himself. Muhammad Adil Shah is linked with the Gol Gumbaz.","difficulty":"very-hard","questionHi":"बीजापुर का इब्राहीम रौज़ा, जो पतली मीनारों वाला एक ही चबूतरे पर मकबरा और मस्जिद है, किसने बनवाया?","optionsHi":["इब्राहीम आदिल शाह द्वितीय","मुहम्मद आदिल शाह","यूसुफ आदिल शाह","अली आदिल शाह प्रथम"],"explanationHi":"इब्राहीम आदिल शाह द्वितीय ने सत्रहवीं शताब्दी के आरंभ में अपनी रानी और स्वयं के लिए मकबरे के रूप में इब्राहीम रौज़ा बनवाया। मुहम्मद आदिल शाह का संबंध गोल गुंबद से है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-124","question":"The Hawa Mahal of Jaipur, with its honeycomb of jharokhas, was built in 1799 by:","options":["Sawai Jai Singh II","Sawai Madho Singh I","Man Singh I","Sawai Pratap Singh"],"answer":3,"explanation":"Sawai Pratap Singh built the Hawa Mahal so that royal women could watch street life unseen. Jai Singh II founded Jaipur and built the Jantar Mantar, and Man Singh I extended the Amber fort.","difficulty":"hard","questionHi":"जयपुर का हवा महल, अपने झरोखों के छत्ते जैसे जाल के साथ, 1799 में किसने बनवाया?","optionsHi":["सवाई जयसिंह द्वितीय","सवाई माधो सिंह प्रथम","मान सिंह प्रथम","सवाई प्रताप सिंह"],"explanationHi":"सवाई प्रताप सिंह ने हवा महल इसलिए बनवाया कि राजघराने की महिलाएँ बिना दिखे गली का जीवन देख सकें। जयसिंह द्वितीय ने जयपुर बसाया और जंतर मंतर बनवाया, तथा मान सिंह प्रथम ने आमेर किले का विस्तार किया।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-art-culture-125","question":"The Gateway of India at Mumbai, designed by George Wittet in the Indo-Saracenic style, commemorates the visit of:","options":["Queen Victoria","King George V and Queen Mary","Edward VII as Prince of Wales","Lord Curzon"],"answer":1,"explanation":"The Gateway of India was built to mark the 1911 landing of King George V and Queen Mary, and it was completed in 1924. It later became the place from which the last British troops left in 1948.","difficulty":"hard","questionHi":"जॉर्ज विटेट द्वारा इंडो-सारासेनिक शैली में बनाया गया मुंबई का गेटवे ऑफ इंडिया किसकी यात्रा की स्मृति में है?","optionsHi":["महारानी विक्टोरिया","राजा जॉर्ज पंचम और रानी मेरी","प्रिंस ऑफ वेल्स के रूप में एडवर्ड सप्तम","लॉर्ड कर्जन"],"explanationHi":"गेटवे ऑफ इंडिया राजा जॉर्ज पंचम और रानी मेरी के 1911 के आगमन की स्मृति में बना और 1924 में पूरा हुआ। बाद में यही वह स्थान बना जहाँ से 1948 में अंतिम ब्रिटिश सैनिक गए।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-art-culture-126","question":"Chhatrapati Shivaji Terminus (formerly Victoria Terminus), a UNESCO World Heritage Site since 2004, was designed by:","options":["F. W. Stevens","George Wittet","William Emerson","Edwin Lutyens"],"answer":0,"explanation":"F. W. Stevens designed Victoria Terminus in a Victorian Gothic Revival style mixed with Indian elements. Wittet designed the Gateway of India, Emerson the Victoria Memorial and Lutyens New Delhi.","difficulty":"hard","questionHi":"छत्रपति शिवाजी टर्मिनस (पूर्व विक्टोरिया टर्मिनस), जो 2004 से यूनेस्को विश्व धरोहर स्थल है, का अभिकल्प किसने बनाया?","optionsHi":["एफ. डब्ल्यू. स्टीवंस","जॉर्ज विटेट","विलियम एमर्सन","एडविन लुटियंस"],"explanationHi":"एफ. डब्ल्यू. स्टीवंस ने विक्टोरिया टर्मिनस का अभिकल्प भारतीय तत्वों से मिली विक्टोरियाई गॉथिक पुनरुद्धार शैली में बनाया। विटेट ने गेटवे ऑफ इंडिया, एमर्सन ने विक्टोरिया मेमोरियल और लुटियंस ने नई दिल्ली बनाई।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-127","question":"The Capitol Complex at Chandigarh, inscribed as a UNESCO World Heritage Site in 2016, was designed by:","options":["Louis Kahn","Walter Burley Griffin","Le Corbusier","Edwin Lutyens"],"answer":2,"explanation":"Le Corbusier designed the Capitol Complex as part of his plan for Chandigarh, and it was inscribed as part of his Architectural Work in 2016. Louis Kahn designed the IIM at Ahmedabad.","difficulty":"moderate","questionHi":"चंडीगढ़ का कैपिटल कॉम्प्लेक्स, जो 2016 में यूनेस्को विश्व धरोहर स्थल बना, किसने अभिकल्पित किया?","optionsHi":["लुई कान","वाल्टर बर्ली ग्रिफिन","ले कार्बूज़िए","एडविन लुटियंस"],"explanationHi":"ले कार्बूज़िए ने चंडीगढ़ की अपनी योजना के अंग के रूप में कैपिटल कॉम्प्लेक्स बनाया और यह 2016 में उनके वास्तु-कार्य के भाग के रूप में सूचीबद्ध हुआ। लुई कान ने अहमदाबाद का आईआईएम बनाया।","source":"SSC CGL · UPSC Prelims"},
  {"id":"history-art-culture-128","question":"On the abacus of the Sarnath lion capital, four animals alternate with four dharmachakras. They are the elephant, the bull, the horse and the:","options":["Tiger","Deer","Camel","Lion"],"answer":3,"explanation":"The abacus carries an elephant, a bull, a horse and a lion, separated by wheels, and only three animals are visible on the national emblem. The capital is of polished Chunar sandstone.","difficulty":"hard","questionHi":"सारनाथ सिंह-शीर्ष के अबेकस पर चार धर्मचक्रों के बीच चार पशु बने हैं। वे हाथी, बैल, घोड़ा और ___ हैं।","optionsHi":["बाघ","हिरण","ऊँट","सिंह"],"explanationHi":"अबेकस पर हाथी, बैल, घोड़ा और सिंह चक्रों से अलग-अलग बने हैं, और राष्ट्रीय प्रतीक में केवल तीन पशु दिखते हैं। यह शीर्ष चुनार के पॉलिश किए बलुआ पत्थर का है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-art-culture-129","question":"'Jahangir Preferring a Sufi Shaikh to Kings', a famous allegorical Mughal painting, is by the artist:","options":["Basawan","Abul Hasan","Bichitr","Daswanth"],"answer":2,"explanation":"Bichitr painted this allegory in which Jahangir offers a book to a Sufi shaikh and turns away from kings and the Ottoman sultan. Basawan and Daswanth worked under Akbar, and Abul Hasan was Jahangir's Nadir-uz-Zaman.","difficulty":"very-hard","questionHi":"प्रसिद्ध रूपकात्मक मुगल चित्र 'जहाँगीर एक सूफी शेख को राजाओं से अधिक महत्व देते हुए' किस कलाकार की कृति है?","optionsHi":["बसावन","अबुल हसन","बिचित्र","दसवंत"],"explanationHi":"बिचित्र ने यह रूपक-चित्र बनाया जिसमें जहाँगीर एक सूफी शेख को पुस्तक देते हैं और राजाओं तथा उस्मानी सुल्तान से मुँह फेरते हैं। बसावन और दसवंत अकबर के काल के थे और अबुल हसन जहाँगीर के नादिर-उज़-ज़मां थे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-130","question":"Aihole in Karnataka, with over a hundred early temples of the Chalukyas, is often called the:","options":["Cradle of Indian temple architecture","Khajuraho of the south","City of the thousand pillars","Land of the rock-cut caves"],"answer":0,"explanation":"Aihole is called the cradle of Indian temple architecture because its early temples, from the 5th to the 8th centuries, show experiments with different forms such as the flat roof and the apsidal plan.","difficulty":"moderate","questionHi":"कर्नाटक का ऐहोल, जहाँ चालुक्यों के सौ से अधिक आरंभिक मंदिर हैं, प्रायः किस नाम से जाना जाता है?","optionsHi":["भारतीय मंदिर स्थापत्य का पालना","दक्षिण का खजुराहो","हजार स्तंभों का नगर","शैलकृत गुफाओं की भूमि"],"explanationHi":"ऐहोल को भारतीय मंदिर स्थापत्य का पालना कहा जाता है क्योंकि पाँचवीं से आठवीं शताब्दी के उसके आरंभिक मंदिरों में सपाट छत और अर्धवृत्ताकार योजना जैसे अलग-अलग रूपों के प्रयोग दिखते हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-art-culture-131","question":"Of the 34 rock-cut caves at Ellora, the Hindu caves, including the Kailasa, are numbered:","options":["1 to 12","13 to 29","30 to 34","1 to 17"],"answer":1,"explanation":"At Ellora, caves 1–12 are Buddhist, 13–29 are Hindu (including the Kailasa as Cave 16) and 30–34 are Jain. They were carved over several centuries, from about the 6th to the 10th.","difficulty":"hard","questionHi":"एलोरा की 34 शैलकृत गुफाओं में कैलास सहित हिंदू गुफाएँ किन संख्याओं की हैं?","optionsHi":["1 से 12","13 से 29","30 से 34","1 से 17"],"explanationHi":"एलोरा में गुफाएँ 1–12 बौद्ध, 13–29 हिंदू (कैलास गुफा 16 सहित) और 30–34 जैन हैं। इन्हें लगभग छठी से दसवीं शताब्दी के बीच कई शताब्दियों में तराशा गया।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-132","question":"Humayun brought two Persian masters to India who laid the foundation of the Mughal school of painting. They were:","options":["Basawan and Daswanth","Mir Sayyid Ali and Abd-us-Samad","Bihzad and Reza Abbasi","Mansur and Bichitr"],"answer":1,"explanation":"Mir Sayyid Ali and Abd-us-Samad came with Humayun from Persia and trained the Indian painters who later formed Akbar's atelier. Basawan and Daswanth were Indian painters of that atelier.","difficulty":"hard","questionHi":"हुमायूँ दो फारसी उस्तादों को भारत लाया जिन्होंने मुगल चित्रकला की नींव रखी। वे कौन थे?","optionsHi":["बसावन और दसवंत","मीर सैयद अली और अब्दुस्समद","बिहज़ाद और रज़ा अब्बासी","मंसूर और बिचित्र"],"explanationHi":"मीर सैयद अली और अब्दुस्समद हुमायूँ के साथ फारस से आए और उन्होंने उन भारतीय चित्रकारों को प्रशिक्षित किया जिनसे बाद में अकबर का चित्रशाला बनी। बसावन और दसवंत उस चित्रशाला के भारतीय चित्रकार थे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-133","question":"Kangra painting reached its peak under Maharaja Sansar Chand and is best known for its:","options":["Bold primary colours and angular faces in the Basohli manner","Large battle scenes drawn in bird's-eye view","Delicate, lyrical treatment of the Radha–Krishna theme in soft colours","Court portraits of Mughal emperors in a naturalistic style"],"answer":2,"explanation":"The Kangra school, which grew from the Guler style, is known for its soft colours, graceful lines and lyrical depiction of Radha and Krishna. Bold colours and angular faces mark the earlier Basohli style.","difficulty":"hard","questionHi":"कांगड़ा चित्रकला महाराजा संसार चंद के समय शिखर पर पहुँची और किस विशेषता के लिए सबसे प्रसिद्ध है?","optionsHi":["बसोहली शैली के चटक मूल रंग और कोणीय चेहरे","पक्षी-दृष्टि से बनाए गए बड़े युद्ध-दृश्य","कोमल रंगों में राधा-कृष्ण विषय का नाजुक, गीतात्मक चित्रण","स्वाभाविक शैली में मुगल बादशाहों के दरबारी चित्र"],"explanationHi":"गुलेर शैली से विकसित कांगड़ा चित्रशैली कोमल रंगों, सुंदर रेखाओं और राधा-कृष्ण के गीतात्मक चित्रण के लिए प्रसिद्ध है। चटक रंग और कोणीय चेहरे पहले की बसोहली शैली की पहचान हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-134","question":"Ibrahim Adil Shah II of Bijapur, a patron of music, is the author of the Kitab-i-Nauras, a collection of:","options":["Dakhni songs in praise of Saraswati and the ragas","Persian ghazals in praise of the Mughal emperor","A treatise on the architecture of the Deccan","A manual of warfare and fort-building"],"answer":0,"explanation":"Kitab-i-Nauras is a collection of songs in Dakhni, composed by Ibrahim Adil Shah II, with invocations to Saraswati and descriptions of ragas. It shows the composite culture of the Deccan courts.","difficulty":"very-hard","questionHi":"बीजापुर का संगीत-प्रेमी शासक इब्राहीम आदिल शाह द्वितीय किताब-ए-नौरस का रचयिता है, जो किसका संग्रह है?","optionsHi":["सरस्वती और रागों की स्तुति वाले दक्खिनी गीत","मुगल बादशाह की प्रशंसा में फारसी ग़ज़लें","दक्कन के वास्तुशास्त्र पर एक ग्रंथ","युद्ध और दुर्ग-निर्माण की एक पुस्तिका"],"explanationHi":"किताब-ए-नौरस इब्राहीम आदिल शाह द्वितीय द्वारा रचे दक्खिनी गीतों का संग्रह है, जिसमें सरस्वती की वंदना और रागों का वर्णन है। यह दक्कन के दरबारों की मिली-जुली संस्कृति दिखाता है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-135","question":"Raja Ravi Varma made his paintings of gods and goddesses available to a mass public by:","options":["Painting them on the walls of temples in Kerala","Printing them as oleographs at his own press near Bombay","Selling them as miniature albums to the princely courts","Teaching them to students at a school in Thanjavur"],"answer":1,"explanation":"Ravi Varma set up the Ravi Varma Press near Bombay in the 1890s and printed oleographs of his paintings, which spread images of gods and goddesses into ordinary homes. This shaped popular religious iconography.","difficulty":"hard","questionHi":"राजा रवि वर्मा ने अपने देवी-देवताओं के चित्र जन-साधारण तक किस प्रकार पहुँचाए?","optionsHi":["केरल के मंदिरों की दीवारों पर चित्र बनाकर","बंबई के निकट अपने छापाखाने में ओलियोग्राफ के रूप में छापकर","रियासती दरबारों को लघु-चित्र एल्बम बेचकर","तंजावुर के विद्यालय में छात्रों को सिखाकर"],"explanationHi":"रवि वर्मा ने 1890 के दशक में बंबई के निकट रवि वर्मा प्रेस लगाया और अपने चित्रों के ओलियोग्राफ छापे, जिनसे देवी-देवताओं की छवियाँ साधारण घरों तक पहुँचीं। इससे लोकप्रिय धार्मिक प्रतिमा-विधान का रूप बना।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-136","question":"The original manuscript of the Constitution of India was illustrated by artists of Shantiniketan led by:","options":["Nandalal Bose","Jamini Roy","M. F. Husain","Abanindranath Tagore"],"answer":0,"explanation":"Nandalal Bose and his students from Shantiniketan decorated the pages of the Constitution with scenes from India's history and culture. Abanindranath Tagore was his teacher and founder of the Bengal school.","difficulty":"hard","questionHi":"भारत के संविधान की मूल पांडुलिपि को शांतिनिकेतन के किन कलाकारों ने सचित्र बनाया, जिनका नेतृत्व कौन कर रहे थे?","optionsHi":["नंदलाल बोस","जामिनी रॉय","एम. एफ. हुसैन","अवनींद्रनाथ टैगोर"],"explanationHi":"नंदलाल बोस और शांतिनिकेतन के उनके छात्रों ने संविधान के पृष्ठों को भारत के इतिहास और संस्कृति के दृश्यों से सजाया। अवनींद्रनाथ टैगोर उनके गुरु और बंगाल स्कूल के संस्थापक थे।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-art-culture-137","question":"Mata ni Pachedi, a hand-painted and block-printed cloth shrine to the Mother Goddess, is made by the:","options":["Chitrakars of Paithan in Maharashtra","Patuas of Bengal","Waghri community of Ahmedabad in Gujarat","Bhil painters of Jhabua in Madhya Pradesh"],"answer":2,"explanation":"Mata ni Pachedi is made by the Waghri community of Gujarat as a portable cloth shrine for the Mother Goddess, in red, black and white. The other communities practise different painting traditions.","difficulty":"hard","questionHi":"माता नी पछेड़ी, माँ देवी का हाथ से चित्रित और ब्लॉक-मुद्रित कपड़े का मंदिर, किसके द्वारा बनाई जाती है?","optionsHi":["महाराष्ट्र के पैठण के चित्रकार","बंगाल के पटुआ","गुजरात में अहमदाबाद का वाघरी समुदाय","मध्य प्रदेश के झाबुआ के भील चित्रकार"],"explanationHi":"माता नी पछेड़ी गुजरात का वाघरी समुदाय लाल, काले और सफेद रंग में माँ देवी के चलते-फिरते कपड़े के मंदिर के रूप में बनाता है। अन्य समुदायों की चित्र-परंपराएँ भिन्न हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-138","question":"Pichwai paintings, large cloth hangings placed behind the image of Shrinathji, are chiefly associated with:","options":["Nathdwara in Rajasthan","Puri in Odisha","Udupi in Karnataka","Guruvayur in Kerala"],"answer":0,"explanation":"Pichwai, meaning that which hangs at the back, is the cloth painting of Nathdwara, painted for the temple of Shrinathji in the Pushtimarg tradition. It shows scenes of Krishna's life and seasonal festivals.","difficulty":"hard","questionHi":"पिछवाई चित्र, श्रीनाथजी की प्रतिमा के पीछे लगाए जाने वाले बड़े कपड़े के परदे, मुख्यतः किससे संबंधित हैं?","optionsHi":["राजस्थान का नाथद्वारा","ओडिशा का पुरी","कर्नाटक का उडुपी","केरल का गुरुवायूर"],"explanationHi":"पिछवाई का अर्थ है पीछे लटकने वाला; यह पुष्टिमार्ग परंपरा में श्रीनाथजी के मंदिर के लिए बनने वाली नाथद्वारा की कपड़े की चित्रकला है। इसमें कृष्ण-लीला और ऋतु-उत्सवों के दृश्य होते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-139","question":"Dhokra metal casting, practised by tribal artisans of Chhattisgarh, Odisha and West Bengal, uses the:","options":["Sand-casting of iron in clay moulds","Lost-wax (cire perdue) technique with non-ferrous metal","Hammering of silver sheets over wooden forms","Inlay of silver wire on a blackened alloy"],"answer":1,"explanation":"Dhokra is a non-ferrous metal casting by the lost-wax process, in which a wax model is covered in clay and then replaced by molten brass. Each piece is therefore unique, as the mould is broken.","difficulty":"hard","questionHi":"छत्तीसगढ़, ओडिशा और पश्चिम बंगाल के आदिवासी शिल्पकारों द्वारा किया जाने वाला ढोकरा धातु-ढलाई किस विधि का उपयोग करता है?","optionsHi":["मिट्टी के साँचों में लोहे की रेत-ढलाई","अलौह धातु के साथ लुप्त-मोम (सिरे पर्द्यू) विधि","लकड़ी के ढाँचों पर चाँदी की चादरों की पिटाई","काले मिश्रधातु पर चाँदी के तार की जड़ाई"],"explanationHi":"ढोकरा लुप्त-मोम विधि से की जाने वाली अलौह धातु-ढलाई है, जिसमें मोम का नमूना मिट्टी से ढककर पिघले पीतल से बदला जाता है। साँचा तोड़ना पड़ता है, इसलिए हर कृति अद्वितीय होती है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-140","question":"Bidriware, a metal handicraft of Bidar in Karnataka, is made by:","options":["Casting brass images by the lost-wax process","Enamelling copper vessels in the minakari style","Carving figures out of sandalwood and ivory","Inlaying silver into a blackened zinc-copper alloy"],"answer":3,"explanation":"Bidriware is made from a zinc-copper alloy that is blackened and inlaid with silver or brass designs. It developed under the Bahmani Sultans, who brought Persian craftsmen to Bidar.","difficulty":"hard","questionHi":"कर्नाटक के बीदर की धातु-हस्तकला बिदरी वेयर किस प्रकार बनती है?","optionsHi":["लुप्त-मोम विधि से पीतल की मूर्तियाँ ढालकर","मीनाकारी शैली में ताँबे के बर्तनों पर रंगीन आवरण चढ़ाकर","चंदन और हाथीदाँत से आकृतियाँ तराशकर","काले किए गए जस्ता-ताँबा मिश्रधातु में चाँदी जड़कर"],"explanationHi":"बिदरी वेयर जस्ता-ताँबा मिश्रधातु से बनता है जिसे काला करके उसमें चाँदी या पीतल की आकृतियाँ जड़ी जाती हैं। यह बहमनी सुल्तानों के काल में विकसित हुआ, जिन्होंने बीदर में फारसी कारीगर बुलाए।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-141","question":"The 'Tanjore Quartet', who gave Bharatanatyam its present repertoire in the early 19th century, were:","options":["Chinnayya, Ponnayya, Sivanandam and Vadivelu","Tyagaraja, Muthuswami Dikshitar, Shyama Shastri and Swati Tirunal","Rukmini Devi, Balasaraswati, E. Krishna Iyer and Gauri Amma","Kelucharan Mohapatra, Pankaj Charan Das, Deba Prasad Das and Mayadhar Raut"],"answer":0,"explanation":"The four brothers Chinnayya, Ponnayya, Sivanandam and Vadivelu, at the Tanjore court of Serfoji II, shaped the sequence of alarippu, jatiswaram, shabdam, varnam and tillana. The other groups belong to Carnatic music, the Bharatanatyam revival and Odissi.","difficulty":"very-hard","questionHi":"'तंजौर चौकड़ी', जिन्होंने उन्नीसवीं शताब्दी के आरंभ में भरतनाट्यम को उसका वर्तमान क्रम दिया, कौन थे?","optionsHi":["चिन्नैया, पोन्नैया, शिवानंदम और वडिवेलु","त्यागराज, मुत्तुस्वामी दीक्षितार, श्यामा शास्त्री और स्वाति तिरुनाल","रुक्मिणी देवी, बालासरस्वती, ई. कृष्ण अय्यर और गौरी अम्मा","केलुचरण महापात्र, पंकज चरण दास, देबा प्रसाद दास और मायाधर राउत"],"explanationHi":"तंजौर के सरफोजी द्वितीय के दरबार में चार भाइयों चिन्नैया, पोन्नैया, शिवानंदम और वडिवेलु ने अलारिप्पु, जतिस्वरम्, शब्दम्, वर्णम् और तिल्लाना का क्रम गढ़ा। अन्य समूह कर्नाटक संगीत, भरतनाट्यम पुनरुद्धार और ओडिसी से जुड़े हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-142","question":"In Bharata's Natyashastra the eight original rasas do NOT include:","options":["Shringara","Karuna","Bibhatsa","Shanta"],"answer":3,"explanation":"Bharata listed eight rasas: shringara, hasya, karuna, raudra, vira, bhayanaka, bibhatsa and adbhuta. Shanta, the ninth rasa of tranquillity, was added by later writers.","difficulty":"hard","questionHi":"भरत के नाट्यशास्त्र के आठ मूल रसों में निम्न में से कौन शामिल नहीं है?","optionsHi":["शृंगार","करुण","बीभत्स","शांत"],"explanationHi":"भरत ने आठ रस गिनाए: शृंगार, हास्य, करुण, रौद्र, वीर, भयानक, बीभत्स और अद्भुत। शांत, शांति का नौवाँ रस, बाद के लेखकों ने जोड़ा।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-143","question":"Dhrupad, a Hindustani vocal form with the sections sthayi, antara, sanchari and abhog, was developed and patronised at the court of:","options":["Sultan Husain Sharqi of Jaunpur","Muhammad Shah 'Rangila' of Delhi","Wajid Ali Shah of Awadh","Man Singh Tomar of Gwalior"],"answer":3,"explanation":"Raja Man Singh Tomar of Gwalior is credited with developing dhrupad in the late 15th and early 16th centuries. Khayal is linked with Husain Sharqi and Muhammad Shah's court, and thumri with Wajid Ali Shah.","difficulty":"hard","questionHi":"ध्रुपद, जिसमें स्थायी, अंतरा, संचारी और आभोग खंड होते हैं, किसके दरबार में विकसित और संरक्षित हुआ?","optionsHi":["जौनपुर के सुल्तान हुसैन शर्की","दिल्ली के मुहम्मद शाह 'रंगीला'","अवध के वाजिद अली शाह","ग्वालियर के मान सिंह तोमर"],"explanationHi":"ग्वालियर के राजा मान सिंह तोमर को पंद्रहवीं के अंत और सोलहवीं शताब्दी के आरंभ में ध्रुपद के विकास का श्रेय दिया जाता है। ख़याल का संबंध हुसैन शर्की और मुहम्मद शाह के दरबार से और ठुमरी का वाजिद अली शाह से है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-144","question":"The khayal form was refined and popularised at the court of Muhammad Shah 'Rangila' by the court musicians:","options":["Sadarang and Adarang","Tansen and Baiju","Haddu Khan and Hassu Khan","Gopal Nayak and Baiju Bawra"],"answer":0,"explanation":"Sadarang (Niyamat Khan) and his nephew Adarang composed many khayal compositions at Muhammad Shah's court in the early 18th century. Haddu and Hassu Khan founded the Gwalior gharana later.","difficulty":"hard","questionHi":"ख़याल शैली को मुहम्मद शाह 'रंगीला' के दरबार में किन दरबारी संगीतज्ञों ने परिष्कृत और लोकप्रिय बनाया?","optionsHi":["सदारंग और अदारंग","तानसेन और बैजू","हद्दू खाँ और हस्सू खाँ","गोपाल नायक और बैजू बावरा"],"explanationHi":"सदारंग (नियामत खाँ) और उनके भतीजे अदारंग ने अठारहवीं शताब्दी के आरंभ में मुहम्मद शाह के दरबार में अनेक ख़याल बंदिशें रचीं। हद्दू और हस्सू खाँ ने बाद में ग्वालियर घराने की नींव रखी।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-145","question":"Which Hindustani tala has sixteen beats divided into four equal vibhags?","options":["Jhaptal","Ektal","Rupak","Teental"],"answer":3,"explanation":"Teental has sixteen beats in four vibhags of four beats each. Jhaptal has ten beats, Ektal twelve and Rupak seven.","difficulty":"moderate","questionHi":"किस हिंदुस्तानी ताल में सोलह मात्राएँ चार बराबर विभागों में बँटी होती हैं?","optionsHi":["झपताल","एकताल","रूपक","तीनताल"],"explanationHi":"तीनताल में सोलह मात्राएँ चार-चार मात्राओं के चार विभागों में होती हैं। झपताल में दस, एकताल में बारह और रूपक में सात मात्राएँ होती हैं।","source":"SSC CGL · State PCS"},
  {"id":"history-art-culture-146","question":"Which of the following is an avanaddha vadya (membranophone) in the traditional classification of Indian instruments?","options":["Veena (a lute-type instrument)","Mridangam (a barrel drum)","Flute (a bamboo wind pipe)","Ghatam (a clay pot)"],"answer":1,"explanation":"Avanaddha vadyas are drums with a stretched skin, such as the mridangam and tabla. The veena is a tata (string) instrument, the flute a sushira (wind) and the ghatam, a clay pot, a ghana (solid) instrument.","difficulty":"moderate","questionHi":"भारतीय वाद्यों के परंपरागत वर्गीकरण में निम्न में से कौन अवनद्ध वाद्य (झिल्ली वाद्य) है?","optionsHi":["वीणा (तार वाला वाद्य)","मृदंगम (बेलनाकार ढोल)","बाँसुरी (बाँस की वायु-नली)","घटम (मिट्टी का घड़ा)"],"explanationHi":"अवनद्ध वाद्य तनी हुई खाल वाले ढोल होते हैं, जैसे मृदंगम और तबला। वीणा तत (तार) वाद्य, बाँसुरी सुषिर (फूँक) वाद्य और मिट्टी का घड़ा घटम घन (ठोस) वाद्य है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-art-culture-147","question":"Shudraka's Mrichchhakatika (The Little Clay Cart), unusual among Sanskrit plays, is a:","options":["Heroic play on the Mahabharata war and its great warriors","Prakarana, with a middle-class hero and courtesan heroine","Allegorical play on abstract qualities like Faith and Wisdom","Natika on a king's love for a princess of a rival court"],"answer":1,"explanation":"Mrichchhakatika is a prakarana, a social play with the Brahmin merchant Charudatta and the courtesan Vasantasena. Most Sanskrit plays take their heroes from kings or epic characters.","difficulty":"very-hard","questionHi":"शूद्रक की मृच्छकटिक (मिट्टी की गाड़ी), संस्कृत नाटकों में अनूठी, कैसा नाटक है?","optionsHi":["महाभारत युद्ध और उसके महान योद्धाओं पर वीर रस का नाटक","प्रकरण, जिसमें मध्यमवर्गीय नायक और गणिका नायिका है","श्रद्धा और प्रज्ञा जैसे अमूर्त गुणों पर रूपकात्मक नाटक","राजा के प्रतिद्वंद्वी दरबार की राजकुमारी के प्रति प्रेम पर नाटिका"],"explanationHi":"मृच्छकटिक एक प्रकरण है, यानी सामाजिक नाटक, जिसमें ब्राह्मण व्यापारी चारुदत्त और गणिका वसंतसेना हैं। अधिकतर संस्कृत नाटकों के नायक राजा या महाकाव्य के पात्र होते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-148","question":"Kutiyattam, recognised by UNESCO in 2008, is a form of:","options":["Folk opera of coastal Karnataka performed by Yakshagana troupes","Street theatre of Tamil Nadu performed by itinerant village troupes","Masked dance-drama of the Vaishnava sattras of Assam","Sanskrit theatre of Kerala performed by the Chakyars"],"answer":3,"explanation":"Kutiyattam is the ancient Sanskrit theatre of Kerala, performed in temple theatres by the Chakyar and Nambiar communities, with Nangiars playing female roles. It was named a Masterpiece of Oral and Intangible Heritage in 2001 and inscribed in 2008.","difficulty":"hard","questionHi":"यूनेस्को द्वारा 2008 में मान्यता प्राप्त कूडियाट्टम किसका रूप है?","optionsHi":["यक्षगान मंडलियों द्वारा प्रस्तुत तटीय कर्नाटक का लोक-ऑपेरा","घुमंतू ग्राम-मंडलियों द्वारा प्रस्तुत तमिलनाडु का नुक्कड़ नाटक","असम के वैष्णव सत्रों का मुखौटा नृत्य-नाट्य","चाक्यारों द्वारा प्रस्तुत केरल का संस्कृत रंगमंच"],"explanationHi":"कूडियाट्टम केरल का प्राचीन संस्कृत रंगमंच है, जो मंदिर-रंगशालाओं में चाक्यार और नांबियार समुदाय प्रस्तुत करते हैं और नंगियार स्त्री पात्र निभाती हैं। इसे 2001 में मौखिक एवं अमूर्त विरासत की उत्कृष्ट कृति घोषित किया गया और 2008 में सूचीबद्ध किया गया।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-149","question":"Silappadikaram, the Tamil epic of Kovalan and Kannagi, was composed by:","options":["Sittalai Sattanar","Kambar","Ilango Adigal","Thiruvalluvar"],"answer":2,"explanation":"Ilango Adigal, traditionally a Chera prince turned Jain monk, composed Silappadikaram. Its sequel Manimekalai is by Sattanar, and Kambar wrote the Tamil Ramayana.","difficulty":"moderate","questionHi":"कोवलन और कण्णगी का तमिल महाकाव्य सिलप्पदिकारम् किसने रचा?","optionsHi":["सित्तलै सात्तनार","कंबर","इलंगो अडिगल","तिरुवल्लुवर"],"explanationHi":"परंपरा के अनुसार चेर राजकुमार से जैन मुनि बने इलंगो अडिगल ने सिलप्पदिकारम् रचा। इसका अगला भाग मणिमेखलै सात्तनार का है और कंबर ने तमिल रामायण लिखी।","source":"SSC CGL · State PCS"},
  {"id":"history-art-culture-150","question":"The Brahmi script, used in the edicts of Ashoka, was deciphered in 1837 by:","options":["Alexander Cunningham","William Jones","Charles Wilkins","James Prinsep"],"answer":3,"explanation":"James Prinsep, secretary of the Asiatic Society of Bengal, deciphered Brahmi in 1837 and so unlocked the Ashokan edicts. Jones founded the Asiatic Society and Wilkins translated the Gita.","difficulty":"moderate","questionHi":"अशोक के अभिलेखों में प्रयुक्त ब्राह्मी लिपि को 1837 में किसने पढ़ा?","optionsHi":["अलेक्जेंडर कनिंघम","विलियम जोन्स","चार्ल्स विल्किन्स","जेम्स प्रिंसेप"],"explanationHi":"एशियाटिक सोसाइटी ऑफ बंगाल के सचिव जेम्स प्रिंसेप ने 1837 में ब्राह्मी को पढ़ा और इस प्रकार अशोक के अभिलेखों का रहस्य खुला। जोन्स ने एशियाटिक सोसाइटी की स्थापना की और विल्किन्स ने गीता का अनुवाद किया।","source":"SSC CGL · UPSC Prelims"},
  {"id":"history-art-culture-151","question":"Which of these is NOT among the six Hill Forts of Rajasthan inscribed on the UNESCO World Heritage List in 2013?","options":["Mehrangarh","Amber","Gagron","Kumbhalgarh"],"answer":0,"explanation":"The serial site comprises Chittorgarh, Kumbhalgarh, Ranthambore, Gagron, Amber and Jaisalmer. Mehrangarh at Jodhpur is a famous hill fort but is not part of the inscription.","difficulty":"very-hard","questionHi":"इनमें से कौन 2013 में यूनेस्को विश्व धरोहर सूची में सम्मिलित राजस्थान के छह पहाड़ी किलों में शामिल नहीं है?","optionsHi":["मेहरानगढ़","आमेर","गागरोन","कुंभलगढ़"],"explanationHi":"इस शृंखला स्थल में चित्तौड़गढ़, कुंभलगढ़, रणथंभौर, गागरोन, आमेर और जैसलमेर शामिल हैं। जोधपुर का मेहरानगढ़ प्रसिद्ध पहाड़ी किला है पर इस सूचीकरण का भाग नहीं है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-152","question":"India's oldest museum, founded in 1814 at Calcutta by the Asiatic Society, is the:","options":["Prince of Wales Museum","National Museum","Indian Museum","Government Museum, Chennai"],"answer":2,"explanation":"The Indian Museum at Kolkata grew out of the Asiatic Society's collections and was founded in 1814 with Nathaniel Wallich as its first superintendent. The Government Museum at Chennai dates from 1851.","difficulty":"moderate","questionHi":"कलकत्ता में एशियाटिक सोसाइटी द्वारा 1814 में स्थापित भारत का सबसे पुराना संग्रहालय कौन सा है?","optionsHi":["प्रिंस ऑफ वेल्स संग्रहालय","राष्ट्रीय संग्रहालय","भारतीय संग्रहालय","सरकारी संग्रहालय, चेन्नई"],"explanationHi":"कोलकाता का भारतीय संग्रहालय एशियाटिक सोसाइटी के संग्रह से बना और 1814 में नैथेनियल वॉलिख के प्रथम अधीक्षक के साथ स्थापित हुआ। चेन्नई का सरकारी संग्रहालय 1851 का है।","source":"SSC CGL · State PCS"},
  {"id":"history-art-culture-153","question":"The Archaeological Survey of India was set up in 1861 with which first Director-General?","options":["John Marshall","Alexander Cunningham","Mortimer Wheeler","James Burgess"],"answer":1,"explanation":"Alexander Cunningham became the first Director-General of the ASI in 1861 under Lord Canning. Marshall reorganised it in 1902 under Curzon, and Wheeler led it from 1944.","difficulty":"hard","questionHi":"भारतीय पुरातत्व सर्वेक्षण की स्थापना 1861 में किस प्रथम महानिदेशक के साथ हुई?","optionsHi":["जॉन मार्शल","अलेक्जेंडर कनिंघम","मॉर्टिमर व्हीलर","जेम्स बर्गेस"],"explanationHi":"अलेक्जेंडर कनिंघम 1861 में लॉर्ड कैनिंग के समय एएसआई के पहले महानिदेशक बने। मार्शल ने 1902 में कर्जन के समय इसे पुनर्गठित किया और व्हीलर ने 1944 से इसका नेतृत्व किया।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-art-culture-154","question":"Samudragupta's gold coins of the 'lyrist' type show him:","options":["Standing beside a sacrificial horse at an altar","Shooting a lion with a bow","Seated on a couch playing the veena","Seated on a throne with the goddess Lakshmi"],"answer":2,"explanation":"The lyrist coins show Samudragupta seated on a couch playing the veena, reflecting his love of music. The archer, lion-slayer and Ashvamedha types show him in other roles.","difficulty":"moderate","questionHi":"समुद्रगुप्त के 'वीणावादक' प्रकार के स्वर्ण सिक्कों में उन्हें किस रूप में दिखाया गया है?","optionsHi":["बलि के घोड़े के पास वेदी पर खड़े","धनुष से सिंह का शिकार करते","आसन पर बैठे वीणा बजाते","लक्ष्मी के साथ सिंहासन पर बैठे"],"explanationHi":"वीणावादक सिक्कों में समुद्रगुप्त आसन पर बैठे वीणा बजाते दिखते हैं, जो उनके संगीत-प्रेम को दर्शाता है। धनुर्धर, सिंह-हंता और अश्वमेध प्रकार के सिक्के उन्हें अन्य रूपों में दिखाते हैं।","source":"SSC CGL · UPSC Prelims"},
  {"id":"history-art-culture-155","question":"Chand Baori, one of the deepest and most geometric stepwells of India, is at:","options":["Abhaneri in Rajasthan","Patan in Gujarat","Adalaj near Ahmedabad","Mehrauli in Delhi"],"answer":0,"explanation":"Chand Baori stands at Abhaneri in Dausa district, Rajasthan, and is attributed to a Chahamana king named Chanda of the 9th century. Rani-ki-Vav is at Patan and Adalaj Vav near Ahmedabad.","difficulty":"hard","questionHi":"भारत की सबसे गहरी और ज्यामितीय बावड़ियों में से एक चाँद बावड़ी कहाँ है?","optionsHi":["राजस्थान का आभानेरी","गुजरात का पाटन","अहमदाबाद के निकट अडालज","दिल्ली का महरौली"],"explanationHi":"चाँद बावड़ी राजस्थान के दौसा जिले के आभानेरी में है और नौवीं शताब्दी के चाहमान राजा चंदा से जोड़ी जाती है। रानी की वाव पाटन में और अडालज वाव अहमदाबाद के निकट है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-156","question":"The Man Mandir palace in the fort of Gwalior, with its carved sandstone and coloured tile-work, was built by:","options":["Raja Bhoj of Dhar","Man Singh Tomar","Mahadji Scindia","Prithviraj Chauhan"],"answer":1,"explanation":"Man Singh Tomar, who ruled Gwalior in the late 15th and early 16th centuries, built the Man Mandir with its glazed tile decoration. It influenced later Mughal and Rajput palace architecture.","difficulty":"hard","questionHi":"ग्वालियर के किले में नक्काशीदार बलुआ पत्थर और रंगीन टाइलों वाला मान मंदिर महल किसने बनवाया?","optionsHi":["धार के राजा भोज","मान सिंह तोमर","महादजी सिंधिया","पृथ्वीराज चौहान"],"explanationHi":"पंद्रहवीं के अंत और सोलहवीं शताब्दी के आरंभ में ग्वालियर पर शासन करने वाले मान सिंह तोमर ने चमकदार टाइल सजावट वाला मान मंदिर बनवाया। इसने बाद की मुगल और राजपूत महल-स्थापत्य को प्रभावित किया।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-157","question":"The Adalaj stepwell near Ahmedabad, completed in 1499, was built by:","options":["Udayamati, queen of Bhima I, builder of the Patan stepwell","Rani Roop Sundari of Idar, a Rajput princess of the north","Begum Sultana, a queen of the Gujarat Sultanate court","Rudabai, wife of the Vaghela chief Veer Singh"],"answer":3,"explanation":"Adalaj Vav was built by Rani Rudabai in memory of her husband, the Vaghela chief Veer Singh, who died in a fight with Mahmud Begarha. Udayamati built the Rani-ki-Vav at Patan in the 11th century.","difficulty":"very-hard","questionHi":"अहमदाबाद के निकट 1499 में पूरी हुई अडालज बावड़ी किसने बनवाई?","optionsHi":["उदयमती, भीम प्रथम की रानी, पाटन की बावड़ी की निर्माता","ईडर की रानी रूप सुंदरी, उत्तर की एक राजपूत राजकुमारी","बेगम सुल्ताना, गुजरात सल्तनत दरबार की एक रानी","वाघेला सरदार वीर सिंह की पत्नी रूदाबाई"],"explanationHi":"अडालज वाव रानी रूदाबाई ने अपने पति वाघेला सरदार वीर सिंह की स्मृति में बनवाई, जो महमूद बेगड़ा से लड़ाई में मारे गए थे। उदयमती ने ग्यारहवीं शताब्दी में पाटन की रानी की वाव बनवाई।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-158","question":"The Ajanta caves were rediscovered in 1819 by a British officer of the Madras Army, who came upon them while on a tiger hunt. He was:","options":["James Prinsep","Robert Gill","John Smith","Alexander Cunningham"],"answer":2,"explanation":"Captain John Smith of the Madras Army stumbled on the caves in 1819 near the Waghora river. Robert Gill later copied the paintings, and Prinsep and Cunningham worked on inscriptions and surveys elsewhere.","difficulty":"hard","questionHi":"अजंता की गुफाओं की 1819 में पुनः खोज मद्रास सेना के एक ब्रिटिश अधिकारी ने की, जो बाघ के शिकार के समय उन तक पहुँचा। वह कौन था?","optionsHi":["जेम्स प्रिंसेप","रॉबर्ट गिल","जॉन स्मिथ","अलेक्जेंडर कनिंघम"],"explanationHi":"मद्रास सेना के कैप्टन जॉन स्मिथ 1819 में वाघोरा नदी के निकट अचानक इन गुफाओं तक पहुँचे। रॉबर्ट गिल ने बाद में चित्रों की प्रतिलिपि बनाई और प्रिंसेप तथा कनिंघम ने अन्यत्र अभिलेखों और सर्वेक्षण पर काम किया।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-art-culture-159","question":"The monolithic statue of Gommateshwara (Bahubali) at Shravanabelagola was commissioned by the minister:","options":["Chamundaraya of the Western Gangas","Hemadri of the Yadavas","Vastupala of the Vaghelas","Todar Mal of Akbar's court"],"answer":0,"explanation":"Chamundaraya, a minister and general of the Western Ganga king Rachamalla IV, had the statue carved around 981. It is the site of the Mahamastakabhisheka held about every twelve years.","difficulty":"hard","questionHi":"श्रवणबेलगोला की एकाश्म गोमटेश्वर (बाहुबली) प्रतिमा किस मंत्री ने बनवाई?","optionsHi":["पश्चिमी गंगों के चामुंडराय","यादवों के हेमाद्रि","वाघेलों के वस्तुपाल","अकबर के दरबार के टोडरमल"],"explanationHi":"पश्चिमी गंग राजा राचमल्ल चतुर्थ के मंत्री और सेनापति चामुंडराय ने लगभग 981 में यह प्रतिमा तराशवाई। यहाँ लगभग हर बारह वर्ष में महामस्तकाभिषेक होता है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-160","question":"Nalanda mahavihara is traditionally said to have been founded in the 5th century under the Gupta ruler:","options":["Chandragupta II","Kumaragupta I","Skandagupta","Harshavardhana"],"answer":1,"explanation":"Tradition and seals attribute the founding of Nalanda to Kumaragupta I. Later rulers such as Harsha and the Palas patronised it, and it was inscribed on the World Heritage List in 2016.","difficulty":"hard","questionHi":"परंपरा के अनुसार नालंदा महाविहार की स्थापना पाँचवीं शताब्दी में किस गुप्त शासक के काल में हुई?","optionsHi":["चंद्रगुप्त द्वितीय","कुमारगुप्त प्रथम","स्कंदगुप्त","हर्षवर्धन"],"explanationHi":"परंपरा और मुहरें नालंदा की स्थापना का श्रेय कुमारगुप्त प्रथम को देती हैं। हर्ष और पालों जैसे बाद के शासकों ने इसे संरक्षण दिया और यह 2016 में विश्व धरोहर सूची में शामिल हुआ।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-161","question":"Tabo Monastery in Spiti, founded in 996 CE, is associated with the great translator:","options":["Rinchen Zangpo","Atisha","Padmasambhava","Tsongkhapa"],"answer":0,"explanation":"Tabo was founded by Rinchen Zangpo, the 'Great Translator' who brought Buddhist texts from Kashmir to the western Himalaya. Atisha visited later, Padmasambhava is the 8th-century teacher of Tibet and Tsongkhapa founded the Gelug order.","difficulty":"very-hard","questionHi":"996 ईस्वी में स्थापित स्पीति का ताबो मठ किस महान अनुवादक से जुड़ा है?","optionsHi":["रिंचेन ज़ंगपो","अतीश","पद्मसंभव","त्सोंगखापा"],"explanationHi":"ताबो की स्थापना 'महान अनुवादक' रिंचेन ज़ंगपो ने की, जो कश्मीर से बौद्ध ग्रंथ पश्चिमी हिमालय लाए। अतीश बाद में आए, पद्मसंभव तिब्बत के आठवीं शताब्दी के आचार्य हैं और त्सोंगखापा ने गेलुग संप्रदाय की स्थापना की।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-162","question":"The Harmandir Sahib at Amritsar was covered with gold leaf in the early 19th century under:","options":["Guru Arjan Dev","Jassa Singh Ahluwalia","Banda Singh Bahadur","Maharaja Ranjit Singh"],"answer":3,"explanation":"Maharaja Ranjit Singh had the upper parts covered with gold, which gave the shrine its name of the Golden Temple. Guru Arjan Dev built the original shrine and Jassa Singh Ahluwalia restored it after Abdali's attack.","difficulty":"hard","questionHi":"अमृतसर के हरमंदिर साहिब पर उन्नीसवीं शताब्दी के आरंभ में सोने की परत किसके काल में चढ़ाई गई?","optionsHi":["गुरु अर्जन देव","जस्सा सिंह अहलूवालिया","बंदा सिंह बहादुर","महाराजा रणजीत सिंह"],"explanationHi":"महाराजा रणजीत सिंह ने ऊपरी भागों पर सोना चढ़वाया, जिससे गुरुद्वारे का नाम स्वर्ण मंदिर पड़ा। गुरु अर्जन देव ने मूल गुरुद्वारा बनवाया और जस्सा सिंह अहलूवालिया ने अब्दाली के हमले के बाद उसका जीर्णोद्धार किया।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-art-culture-163","question":"The Mecca Masjid of Hyderabad was begun by Muhammad Quli Qutb Shah and completed in 1694 by:","options":["Abdullah Qutb Shah","Aurangzeb","Abul Hasan Tana Shah","Nizam-ul-Mulk Asaf Jah I"],"answer":1,"explanation":"The Qutb Shahis began the mosque in 1617, and Aurangzeb, after conquering Golconda in 1687, had it completed in 1694. The Asaf Jahis came later, in the 18th century.","difficulty":"very-hard","questionHi":"हैदराबाद की मक्का मस्जिद का निर्माण मुहम्मद क़ुली क़ुतुब शाह ने शुरू किया और 1694 में किसने पूरा किया?","optionsHi":["अब्दुल्ला क़ुतुब शाह","औरंगज़ेब","अबुल हसन तानाशाह","निज़ामुल्मुल्क आसफ़ जाह प्रथम"],"explanationHi":"क़ुतुबशाहियों ने मस्जिद 1617 में शुरू की और 1687 में गोलकुंडा जीतने के बाद औरंगज़ेब ने उसे 1694 में पूरा कराया। आसफ़जाही बाद में अठारहवीं शताब्दी में आए।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-164","question":"The Basilica of Bom Jesus at Old Goa, a UNESCO World Heritage Site, preserves the relics of:","options":["St Thomas","St Anthony","St Francis Xavier","St Ignatius Loyola"],"answer":2,"explanation":"The Basilica of Bom Jesus holds the preserved body of St Francis Xavier, who died in 1552. St Thomas is linked with Mylapore and Loyola founded the Jesuit order.","difficulty":"moderate","questionHi":"ओल्ड गोवा का बॉम जीसस बेसिलिका, जो यूनेस्को विश्व धरोहर स्थल है, किसके अवशेष सुरक्षित रखता है?","optionsHi":["सेंट थॉमस","सेंट एंथनी","सेंट फ्रांसिस ज़ेवियर","सेंट इग्नेशियस लोयोला"],"explanationHi":"बॉम जीसस बेसिलिका में 1552 में दिवंगत सेंट फ्रांसिस ज़ेवियर का संरक्षित शरीर रखा है। सेंट थॉमस का संबंध मायलापुर से है और लोयोला ने जेसुइट संघ की स्थापना की।","source":"SSC CGL · State PCS"},
  {"id":"history-art-culture-165","question":"The first Jnanpith Award, given in 1965, went to a writer in:","options":["Malayalam","Bengali","Hindi","Tamil"],"answer":0,"explanation":"The first Jnanpith Award went to G. Sankara Kurup for his Malayalam poetry collection Odakkuzhal. The next awards went to writers in Bengali and Hindi.","difficulty":"hard","questionHi":"1965 में दिया गया पहला ज्ञानपीठ पुरस्कार किस भाषा के लेखक को मिला?","optionsHi":["मलयालम","बंगला","हिंदी","तमिल"],"explanationHi":"पहला ज्ञानपीठ पुरस्कार जी. शंकर कुरुप को उनके मलयालम काव्य-संग्रह 'ओडक्कुझल' के लिए मिला। अगले पुरस्कार बंगला और हिंदी के लेखकों को मिले।","source":"SSC CGL · State PCS"},
  {"id":"history-art-culture-166","question":"Which language was the first to be given the status of a classical language in India, in 2004?","options":["Sanskrit","Tamil","Kannada","Telugu"],"answer":1,"explanation":"Tamil was declared the first classical language in 2004, and Sanskrit followed in 2005. Kannada and Telugu were recognised in 2008.","difficulty":"hard","questionHi":"2004 में भारत में शास्त्रीय भाषा का दर्जा पाने वाली पहली भाषा कौन सी थी?","optionsHi":["संस्कृत","तमिल","कन्नड़","तेलुगु"],"explanationHi":"2004 में तमिल को पहली शास्त्रीय भाषा घोषित किया गया और 2005 में संस्कृत को। कन्नड़ और तेलुगु को 2008 में मान्यता मिली।","source":"SSC CGL · UPSC Prelims"},
  {"id":"history-art-culture-167","question":"Which Indian city was the first to be inscribed as a UNESCO World Heritage City, in 2017?","options":["Jaipur","Varanasi","Delhi","Ahmedabad"],"answer":3,"explanation":"The Historic City of Ahmadabad was inscribed in 2017 as India's first World Heritage City, noted for its pols and its Indo-Islamic monuments. Jaipur followed in 2019.","difficulty":"hard","questionHi":"2017 में यूनेस्को की विश्व धरोहर नगर के रूप में सूचीबद्ध होने वाला भारत का पहला शहर कौन सा था?","optionsHi":["जयपुर","वाराणसी","दिल्ली","अहमदाबाद"],"explanationHi":"ऐतिहासिक नगर अहमदाबाद 2017 में भारत के पहले विश्व धरोहर नगर के रूप में सूचीबद्ध हुआ, जो अपनी पोलों और इंडो-इस्लामी स्मारकों के लिए प्रसिद्ध है। जयपुर 2019 में जुड़ा।","source":"SSC CGL · State PCS"},
  {"id":"history-art-culture-168","question":"The Champaner-Pavagadh Archaeological Park in Gujarat is unique among India's World Heritage Sites because it preserves:","options":["A Harappan port town with a dockyard and tidal basin","A complete garden-city of Mughal pavilions built by Akbar's architects","A rock-cut complex of Buddhist monasteries and chaitya halls","An unaltered pre-Mughal Islamic city with Hindu and Jain monuments"],"answer":3,"explanation":"Champaner-Pavagadh, inscribed in 2004, preserves a 15th-century Sultanate city of Gujarat with the Jami Masjid and with Hindu and Jain temples on Pavagadh hill. It is regarded as the only complete and unchanged Islamic pre-Mughal city of this kind.","difficulty":"hard","questionHi":"गुजरात का चांपानेर-पावागढ़ पुरातत्व उद्यान भारत के विश्व धरोहर स्थलों में अनूठा क्यों है?","optionsHi":["यह गोदी और ज्वारीय बेसिन वाला हड़प्पाई बंदरगाह नगर है","यह अकबर के वास्तुकारों द्वारा बनाया मुगल मंडपों वाला पूरा उद्यान-नगर है","यह बौद्ध विहारों और चैत्य गृहों वाला शैलकृत परिसर है","यह हिंदू और जैन स्मारकों वाला अपरिवर्तित मुगल-पूर्व इस्लामी नगर है"],"explanationHi":"2004 में सूचीबद्ध चांपानेर-पावागढ़ गुजरात की पंद्रहवीं शताब्दी की सल्तनतकालीन नगरी को जामा मस्जिद और पावागढ़ पहाड़ी के हिंदू तथा जैन मंदिरों के साथ सुरक्षित रखता है। इसे इस प्रकार की एकमात्र पूर्ण और अपरिवर्तित मुगल-पूर्व इस्लामी नगरी माना जाता है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-169","question":"Which of the three national akademis was set up first, in 1953?","options":["Sangeet Natak Akademi","Sahitya Akademi","Lalit Kala Akademi","National School of Drama"],"answer":0,"explanation":"The Sangeet Natak Akademi was inaugurated in January 1953 as the first national academy of the arts. The Sahitya Akademi and the Lalit Kala Akademi followed in 1954, and the National School of Drama in 1959.","difficulty":"very-hard","questionHi":"तीन राष्ट्रीय अकादमियों में से कौन सी 1953 में सबसे पहले स्थापित हुई?","optionsHi":["संगीत नाटक अकादमी","साहित्य अकादमी","ललित कला अकादमी","राष्ट्रीय नाट्य विद्यालय"],"explanationHi":"संगीत नाटक अकादमी का उद्घाटन जनवरी 1953 में कलाओं की पहली राष्ट्रीय अकादमी के रूप में हुआ। साहित्य अकादमी और ललित कला अकादमी 1954 में और राष्ट्रीय नाट्य विद्यालय 1959 में बने।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-170","question":"The Ancient Monuments Preservation Act of 1904, which empowered the government to protect monuments, was passed under the Viceroy:","options":["Lord Canning","Lord Curzon","Lord Dufferin","Lord Lytton"],"answer":1,"explanation":"Lord Curzon, who took a keen interest in monuments, had the Act passed in 1904 and revived the ASI under John Marshall. Canning had founded the ASI in 1861.","difficulty":"hard","questionHi":"1904 का प्राचीन स्मारक संरक्षण अधिनियम, जिसने सरकार को स्मारकों की रक्षा का अधिकार दिया, किस वायसराय के समय पारित हुआ?","optionsHi":["लॉर्ड कैनिंग","लॉर्ड कर्जन","लॉर्ड डफरिन","लॉर्ड लिटन"],"explanationHi":"स्मारकों में गहरी रुचि लेने वाले लॉर्ड कर्जन ने 1904 में यह अधिनियम पारित कराया और जॉन मार्शल के अधीन एएसआई को पुनर्जीवित किया। कैनिंग ने 1861 में एएसआई की स्थापना की थी।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-art-culture-171","question":"Match the festival with its state: A. Bonalu B. Sarhul C. Ambubachi D. Gangaur. States: 1. Assam 2. Rajasthan 3. Jharkhand 4. Telangana","options":["A-3, B-4, C-2, D-1","A-4, B-1, C-3, D-2","A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2"],"answer":3,"explanation":"Bonalu is the festival of Goddess Mahakali in Hyderabad and Telangana, Sarhul the spring festival of the tribes of Jharkhand, Ambubachi the Mela at the Kamakhya temple in Assam and Gangaur is celebrated in Rajasthan.","difficulty":"very-hard","questionHi":"त्योहार का उसके राज्य से मिलान कीजिए: A. बोनालू B. सरहुल C. अंबुबाची D. गणगौर। राज्य: 1. असम 2. राजस्थान 3. झारखंड 4. तेलंगाना","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-1, C-3, D-2","A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"बोनालू हैदराबाद और तेलंगाना में देवी महाकाली का पर्व है, सरहुल झारखंड की जनजातियों का वसंत पर्व, अंबुबाची असम के कामाख्या मंदिर का मेला और गणगौर राजस्थान में मनाया जाता है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-172","question":"Match the textile with its state: A. Paithani B. Baluchari C. Chanderi D. Pochampally. States: 1. Madhya Pradesh 2. West Bengal 3. Telangana 4. Maharashtra","options":["A-4, B-2, C-1, D-3","A-4, B-1, C-2, D-3","A-2, B-4, C-1, D-3","A-4, B-2, C-3, D-1"],"answer":0,"explanation":"Paithani silk comes from Maharashtra (Paithan and Yeola), Baluchari from Bishnupur in West Bengal, Chanderi from Madhya Pradesh and Pochampally ikat from Telangana.","difficulty":"very-hard","questionHi":"वस्त्र का उसके राज्य से मिलान कीजिए: A. पैठणी B. बालूचरी C. चंदेरी D. पोचमपल्ली। राज्य: 1. मध्य प्रदेश 2. पश्चिम बंगाल 3. तेलंगाना 4. महाराष्ट्र","optionsHi":["A-4, B-2, C-1, D-3","A-4, B-1, C-2, D-3","A-2, B-4, C-1, D-3","A-4, B-2, C-3, D-1"],"explanationHi":"पैठणी रेशम महाराष्ट्र (पैठण और येवला) का, बालूचरी पश्चिम बंगाल के बिष्णुपुर का, चंदेरी मध्य प्रदेश का और पोचमपल्ली इकत तेलंगाना का है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-173","question":"Match the craft with its state: A. Kondapalli toys B. Channapatna toys C. Longpi pottery D. Blue pottery. States: 1. Manipur 2. Andhra Pradesh 3. Rajasthan 4. Karnataka","options":["A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3"],"answer":2,"explanation":"Kondapalli wooden toys are from Andhra Pradesh, Channapatna lacquered toys from Karnataka, Longpi black pottery from Manipur and blue pottery from Jaipur, Rajasthan.","difficulty":"very-hard","questionHi":"शिल्प का उसके राज्य से मिलान कीजिए: A. कोंडापल्ली खिलौने B. चन्नपट्टन खिलौने C. लोंगपी मिट्टी के बर्तन D. नीली मिट्टी के बर्तन। राज्य: 1. मणिपुर 2. आंध्र प्रदेश 3. राजस्थान 4. कर्नाटक","optionsHi":["A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3"],"explanationHi":"कोंडापल्ली के लकड़ी के खिलौने आंध्र प्रदेश के, चन्नपट्टन के लाख के खिलौने कर्नाटक के, लोंगपी काले मिट्टी के बर्तन मणिपुर के और नीली मिट्टी के बर्तन राजस्थान के जयपुर के हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-174","question":"Arrange in chronological order: 1. Archaeological Survey of India founded 2. Asiatic Society founded 3. Ancient Monuments Preservation Act 4. Indian Museum founded","options":["2-1-4-3","2-4-1-3","4-2-1-3","2-4-3-1"],"answer":1,"explanation":"The Asiatic Society was founded in 1784, the Indian Museum in 1814, the ASI in 1861 and the Ancient Monuments Preservation Act was passed in 1904.","difficulty":"very-hard","questionHi":"कालक्रम में व्यवस्थित कीजिए: 1. भारतीय पुरातत्व सर्वेक्षण की स्थापना 2. एशियाटिक सोसाइटी की स्थापना 3. प्राचीन स्मारक संरक्षण अधिनियम 4. भारतीय संग्रहालय की स्थापना","optionsHi":["2-1-4-3","2-4-1-3","4-2-1-3","2-4-3-1"],"explanationHi":"एशियाटिक सोसाइटी 1784 में, भारतीय संग्रहालय 1814 में, एएसआई 1861 में स्थापित हुए और प्राचीन स्मारक संरक्षण अधिनियम 1904 में पारित हुआ।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-175","question":"Arrange these temples in order of construction: 1. Konark Sun Temple 2. Kandariya Mahadeva temple, Khajuraho 3. Brihadisvara temple, Thanjavur 4. Hoysaleswara temple, Halebidu","options":["3-4-2-1","2-3-4-1","3-2-1-4","3-2-4-1"],"answer":3,"explanation":"The Brihadisvara temple was completed around 1010, the Kandariya Mahadeva around 1030, the Hoysaleswara in the mid 12th century and the Konark temple around 1250.","difficulty":"very-hard","questionHi":"इन मंदिरों को निर्माण के क्रम में व्यवस्थित कीजिए: 1. कोणार्क सूर्य मंदिर 2. खजुराहो का कंदरिया महादेव मंदिर 3. तंजावुर का बृहदीश्वर मंदिर 4. हलेबीडु का होयसलेश्वर मंदिर","optionsHi":["3-4-2-1","2-3-4-1","3-2-1-4","3-2-4-1"],"explanationHi":"बृहदीश्वर मंदिर लगभग 1010 में, कंदरिया महादेव लगभग 1030 में, होयसलेश्वर बारहवीं शताब्दी के मध्य में और कोणार्क मंदिर लगभग 1250 में पूर्ण हुआ।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-176","question":"How many of these statements about Mughal gardens are correct? I. The Shalimar Bagh at Srinagar was laid out by Jahangir. II. The Shalimar Bagh at Lahore was built under Shah Jahan. III. The Pinjore Garden was laid out by Fidai Khan, a foster brother of Aurangzeb. IV. The Nishat Bagh at Srinagar was laid out by Nur Jahan.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The Nishat Bagh was laid out by Asaf Khan, Nur Jahan's brother, not by Nur Jahan herself.","difficulty":"very-hard","questionHi":"मुगल उद्यानों के बारे में इनमें से कितने कथन सही हैं? I. श्रीनगर का शालीमार बाग जहाँगीर ने बनवाया। II. लाहौर का शालीमार बाग शाहजहाँ के काल में बना। III. पिंजौर उद्यान औरंगज़ेब के दूध-भाई फिदाई खान ने बनवाया। IV. श्रीनगर का निशात बाग नूरजहाँ ने बनवाया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। निशात बाग नूरजहाँ के भाई आसफ़ ख़ान ने बनवाया था, स्वयं नूरजहाँ ने नहीं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-177","question":"Assertion (A): Chola bronze images are each unique. Reason (R): In the lost-wax method the clay mould has to be broken to remove the image, so it can be used only once.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"In lost-wax casting a wax model is coated in clay and melted out, and the mould is broken after the metal is poured, so no two castings are alike. This explains why Chola bronzes are unique.","difficulty":"hard","questionHi":"अभिकथन (A): चोल कांस्य मूर्तियाँ प्रत्येक अद्वितीय होती हैं। कारण (R): लुप्त-मोम विधि में मूर्ति निकालने के लिए मिट्टी का साँचा तोड़ना पड़ता है, इसलिए उसका एक ही बार उपयोग हो सकता है।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, पर R, A की सही व्याख्या नहीं है","A सही है, पर R गलत है","A गलत है, पर R सही है"],"explanationHi":"लुप्त-मोम ढलाई में मोम के नमूने पर मिट्टी चढ़ाकर उसे पिघलाया जाता है और धातु डालने के बाद साँचा तोड़ा जाता है, इसलिए दो ढलाइयाँ एक जैसी नहीं होतीं। यही चोल कांस्य के अद्वितीय होने की व्याख्या है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-178","question":"Assertion (A): The Hoysala temples show remarkably fine, lace-like carving. Reason (R): They were built of soapstone, which is soft when quarried and hardens on exposure.","options":["A is true, but R is false","Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A","A is false, but R is true"],"answer":2,"explanation":"Hoysala builders used chloritic schist (soapstone), which is easy to carve when freshly quarried and hardens in the air. This allowed the intricate jewellery-like detail seen at Belur and Halebidu.","difficulty":"very-hard","questionHi":"अभिकथन (A): होयसल मंदिरों में अत्यंत बारीक, जालीदार नक्काशी दिखती है। कारण (R): वे सेलखड़ी से बने थे, जो खदान से निकलने पर मुलायम और खुले में कठोर हो जाती है।","optionsHi":["A सही है, पर R गलत है","A और R दोनों सही हैं, पर R, A की सही व्याख्या नहीं है","A और R दोनों सही हैं, और R, A की सही व्याख्या है","A गलत है, पर R सही है"],"explanationHi":"होयसल शिल्पियों ने क्लोराइटिक शिस्ट (सेलखड़ी) का प्रयोग किया, जो ताज़ा निकलने पर तराशने में आसान और हवा में कठोर हो जाती है। इसी से बेलूर और हलेबीडु में गहनों जैसा बारीक अलंकरण संभव हुआ।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-179","question":"Assertion (A): Mughal painting developed a distinctly Indian character under Akbar. Reason (R): Akbar's atelier employed many Hindu painters who worked alongside the Persian masters.","options":["Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Under Akbar, Indian painters such as Basawan and Daswanth worked with the Persian masters, and their fusion of styles gave Mughal painting its Indian character. Both statements are true and R explains A.","difficulty":"hard","questionHi":"अभिकथन (A): अकबर के काल में मुगल चित्रकला ने विशिष्ट भारतीय स्वरूप पाया। कारण (R): अकबर की चित्रशाला में अनेक हिंदू चित्रकार फारसी उस्तादों के साथ काम करते थे।","optionsHi":["A और R दोनों सही हैं, पर R, A की सही व्याख्या नहीं है","A और R दोनों सही हैं, और R, A की सही व्याख्या है","A सही है, पर R गलत है","A गलत है, पर R सही है"],"explanationHi":"अकबर के काल में बसावन और दसवंत जैसे भारतीय चित्रकारों ने फारसी उस्तादों के साथ काम किया और शैलियों के मेल से मुगल चित्रकला को भारतीय स्वरूप मिला। दोनों कथन सही हैं और R, A की व्याख्या करता है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-180","question":"How many of these statements about early Indian sculpture are correct? I. Early Buddhist art at Bharhut and Sanchi shows the Buddha through symbols such as the stupa and footprints. II. The Mathura school used spotted red sandstone. III. The Gandhara school used spotted red sandstone. IV. The Amaravati school used grey schist.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. Gandhara used grey-blue schist and stucco, and Amaravati used a white-green limestone, so III and IV are wrong.","difficulty":"very-hard","questionHi":"आरंभिक भारतीय मूर्तिकला के बारे में इनमें से कितने कथन सही हैं? I. भरहुत और साँची की आरंभिक बौद्ध कला में बुद्ध को स्तूप और पदचिह्न जैसे प्रतीकों से दिखाया गया है। II. मथुरा शैली में चित्तीदार लाल बलुआ पत्थर प्रयुक्त हुआ। III. गांधार शैली में चित्तीदार लाल बलुआ पत्थर प्रयुक्त हुआ। IV. अमरावती शैली में धूसर शिस्ट प्रयुक्त हुआ।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। गांधार में धूसर-नीली शिस्ट और गारे का तथा अमरावती में सफेद-हरे चूना पत्थर का प्रयोग हुआ, इसलिए III और IV गलत हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-181","question":"The Mattancherry (Dutch) Palace at Kochi, famous for its murals of the Ramayana, was built by the Portuguese in about 1555 as a gift to:","options":["Marthanda Varma of Travancore","The Zamorin of Calicut","Tipu Sultan of Mysore","Veera Kerala Varma of Cochin"],"answer":3,"explanation":"The Portuguese built the palace for the Raja of Cochin, Veera Kerala Varma, and the Dutch renovated it in 1663, which gave it the name Dutch Palace. Its murals are among the finest of Kerala's mural tradition.","difficulty":"very-hard","questionHi":"कोच्चि का मट्टानचेरी (डच) महल, जो रामायण के भित्ति-चित्रों के लिए प्रसिद्ध है, लगभग 1555 में पुर्तगालियों ने किसे उपहार देने के लिए बनाया?","optionsHi":["त्रावणकोर के मार्तंड वर्मा को","कालीकट के ज़मोरिन को","मैसूर के टीपू सुल्तान को","कोचीन के वीर केरल वर्मा को"],"explanationHi":"पुर्तगालियों ने यह महल कोचीन के राजा वीर केरल वर्मा के लिए बनाया और डचों ने 1663 में इसका जीर्णोद्धार किया, जिससे इसे डच महल नाम मिला। इसके भित्ति-चित्र केरल की भित्ति-चित्र परंपरा के उत्कृष्ट नमूनों में हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-182","question":"The Sun Temple at Konark, conceived as a chariot with twenty-four wheels, was built by the Eastern Ganga king:","options":["Anantavarman Chodaganga","Kapilendra Deva","Anangabhima III","Narasimhadeva I"],"answer":3,"explanation":"Narasimhadeva I of the Eastern Ganga dynasty built the Konark temple in the 13th century. Chodaganga is linked with the Jagannath temple at Puri.","difficulty":"hard","questionHi":"चौबीस पहियों वाले रथ के रूप में परिकल्पित कोणार्क का सूर्य मंदिर किस पूर्वी गंग राजा ने बनवाया?","optionsHi":["अनंतवर्मन चोडगंग","कपिलेंद्र देव","अनंगभीम तृतीय","नरसिंहदेव प्रथम"],"explanationHi":"पूर्वी गंग वंश के नरसिंहदेव प्रथम ने तेरहवीं शताब्दी में कोणार्क का मंदिर बनवाया। चोडगंग का संबंध पुरी के जगन्नाथ मंदिर से है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-183","question":"The present Mahabodhi temple at Bodh Gaya, a World Heritage Site since 2002, dates in its early form to the Gupta period and is among the earliest Indian temples built wholly of:","options":["Granite","Marble","Brick","Sandstone"],"answer":2,"explanation":"The Mahabodhi temple is one of the earliest surviving brick temples in India, with its tall tapering tower. It was repaired several times, and Burmese kings carried out repairs in the medieval period.","difficulty":"very-hard","questionHi":"बोधगया का वर्तमान महाबोधि मंदिर, जो 2002 से विश्व धरोहर स्थल है, अपने आरंभिक रूप में गुप्त काल का है और भारत के सबसे पुराने पूर्णतः किससे बने मंदिरों में है?","optionsHi":["ग्रेनाइट","संगमरमर","ईंट","बलुआ पत्थर"],"explanationHi":"महाबोधि मंदिर भारत के सबसे पुराने बचे ईंट के मंदिरों में है, जिसका शिखर ऊँचा और क्रमशः पतला होता गया है। इसकी कई बार मरम्मत हुई और मध्यकाल में बर्मी राजाओं ने भी मरम्मत कराई।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-184","question":"Jaisalmer Fort, called the 'Golden Fort' for its yellow sandstone and still home to residents, was founded in 1156 by:","options":["Rana Kumbha","Rao Jodha","Rawal Jaisal","Raja Anangpal"],"answer":2,"explanation":"The Bhati Rajput Rawal Jaisal founded the fort and the city of Jaisalmer in 1156. Rao Jodha founded Jodhpur's Mehrangarh and Rana Kumbha built Kumbhalgarh.","difficulty":"hard","questionHi":"पीले बलुआ पत्थर के कारण 'सोनार किला' कहलाने वाला और आज भी निवासियों वाला जैसलमेर किला 1156 में किसने बनवाया?","optionsHi":["राणा कुंभा","राव जोधा","रावल जैसल","राजा अनंगपाल"],"explanationHi":"भाटी राजपूत रावल जैसल ने 1156 में किले और जैसलमेर नगर की स्थापना की। राव जोधा ने जोधपुर का मेहरानगढ़ बनवाया और राणा कुंभा ने कुंभलगढ़।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-art-culture-185","question":"The santoor, a hundred-stringed hammered instrument, originated in the folk and Sufiana music of:","options":["Punjab","Kashmir","Bengal","Kerala"],"answer":1,"explanation":"The santoor comes from the Sufiana music of Kashmir, and Shivkumar Sharma introduced it to Hindustani classical music. Its Persian relative is the santur.","difficulty":"moderate","questionHi":"सौ तारों वाला हथौड़ी से बजने वाला वाद्य संतूर किसके लोक और सूफियाना संगीत से उत्पन्न हुआ?","optionsHi":["पंजाब","कश्मीर","बंगाल","केरल"],"explanationHi":"संतूर कश्मीर के सूफियाना संगीत से आया और शिवकुमार शर्मा ने उसे हिंदुस्तानी शास्त्रीय संगीत में प्रतिष्ठित किया। इसका फारसी संबंधी वाद्य संतूर (santur) है।","source":"SSC CGL · State PCS"},
  {"id":"history-art-culture-186","question":"The Chamba Rumal, an embroidered handkerchief of Himachal Pradesh inspired by Pahari miniatures, is worked in:","options":["Dorukha stitch, so that the pattern is identical on both faces","Running stitch quilted in several layers","Cross-stitch counted on a coarse cotton ground","Couching with gold thread over a padded base"],"answer":0,"explanation":"The Chamba Rumal is embroidered in dorukha (double satin) stitch, which makes the design appear equally on both sides of the cloth. It shows scenes from the Pahari miniature paintings.","difficulty":"very-hard","questionHi":"पहाड़ी लघु-चित्रों से प्रेरित हिमाचल प्रदेश का कढ़ाईदार रूमाल चंबा रूमाल किस टाँके में बनता है?","optionsHi":["दोरुखा टाँके में, जिससे आकृति दोनों ओर एक जैसी दिखती है","कई परतों में रजाई की तरह दौड़ने वाले टाँके में","मोटे सूती आधार पर गिन-गिनकर किए गए क्रॉस-टाँके में","गद्देदार आधार पर सोने के तार की कोचिंग में"],"explanationHi":"चंबा रूमाल दोरुखा (दोहरे साटन) टाँके में कढ़ा जाता है, जिससे आकृति कपड़े के दोनों ओर समान दिखती है। इसमें पहाड़ी लघु-चित्रों के दृश्य होते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-187","question":"How many of these statements about classical dances are correct? I. The tribhanga posture is a characteristic of Odissi. II. Kuchipudi is traditionally performed only by women. III. Mohiniyattam is set mainly to Hindustani music. IV. In Kathakali the female roles are traditionally played by women.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. Kuchipudi was traditionally danced by men, Mohiniyattam uses Carnatic music with Malayalam lyrics, and in Kathakali the female roles are traditionally played by men.","difficulty":"very-hard","questionHi":"शास्त्रीय नृत्यों के बारे में इनमें से कितने कथन सही हैं? I. त्रिभंग मुद्रा ओडिसी की विशेषता है। II. कुचिपुड़ी परंपरा से केवल महिलाओं द्वारा किया जाता है। III. मोहिनीअट्टम मुख्यतः हिंदुस्तानी संगीत पर आधारित है। IV. कथकली में स्त्री भूमिकाएँ परंपरा से महिलाएँ निभाती हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है। कुचिपुड़ी परंपरा से पुरुष करते थे, मोहिनीअट्टम में मलयालम बोलों के साथ कर्नाटक संगीत होता है और कथकली में स्त्री भूमिकाएँ परंपरा से पुरुष निभाते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-art-culture-188","question":"Badami Cave 3, dedicated to Vishnu, bears an inscription of 578 CE issued under which Chalukya king?","options":["Pulakeshin I","Kirtivarman I","Mangalesha","Vikramaditya II"],"answer":2,"explanation":"Cave 3 at Badami was dedicated to Vishnu in 578 CE under Mangalesha, as recorded in its inscription. Pulakeshin I had founded Vatapi and Vikramaditya II belonged to the 8th century.","difficulty":"very-hard","questionHi":"विष्णु को समर्पित बादामी की गुफा 3 में 578 ईस्वी का अभिलेख किस चालुक्य राजा के काल का है?","optionsHi":["पुलकेशिन प्रथम","कीर्तिवर्मन प्रथम","मंगलेश","विक्रमादित्य द्वितीय"],"explanationHi":"बादामी की गुफा 3 अपने अभिलेख के अनुसार 578 ईस्वी में मंगलेश के काल में विष्णु को समर्पित हुई। पुलकेशिन प्रथम ने वातापी की स्थापना की थी और विक्रमादित्य द्वितीय आठवीं शताब्दी के थे।","source":"UPSC Prelims · State PCS"},
];

